(13915, 121111, 'Paramagnetic', 'Diamagnetic, with a calculated magnetic moment of zero', 'Highly magnetic', 'Radioactive', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13916, 121112, 'Total energy of all d-orbitals combined', 'Energy gap between the higher-energy eg set and lower-energy t2g set of d-orbitals', 'The bond length in the complex', 'The overall charge of the complex', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13917, 121113, 'I- (iodide)', 'Cl- (chloride)', 'CN- (cyanide)', 'H2O (water)', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
