(14177, 121623, 'Simple alkane', 'Beta-hydroxy aldehyde/ketone (aldol), which can further dehydrate to give an alpha,beta-unsaturated carbonyl compound', 'Ether', 'Alcohol only, with no carbonyl group remaining', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14178, 121624, 'Only a single carboxylic acid product', 'One equivalent each of the corresponding alcohol and carboxylic acid (or their salts), via simultaneous reduction and oxidation of two aldehyde molecules', 'Only an ether', 'No reaction occurs at all', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
