(14180, 121626, 'No resonance at all', 'Resonance delocalization of the negative charge equally over both oxygen atoms, providing extra stability compared to a simple alkoxide or phenoxide ion', 'Only inductive effects, with no resonance contribution', 'A permanent positive charge', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14181, 121627, 'Acetic acid < phenol < ethanol', 'Ethanol < phenol < acetic acid', 'Phenol < ethanol < acetic acid', 'All three have identical acidity', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
