(14184, 121630, 'Only carbon dioxide', 'Water, in a reversible equilibrium reaction (Fischer esterification)', 'Hydrogen gas', 'No byproduct at all', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14185, 121631, '-COOH', '-COO- (a carbonyl linked to an -O-R group), formally derived from a carboxylic acid and alcohol', '-CHO', '-OH', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
