(14209, 121705, 'Less', 'More', 'Equally', 'Amines cannot be compared to ammonia in basicity', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14210, 121706, 'More', 'Less, since resonance donation into the ring reduces the lone pair\'s availability for protonation', 'Equally', 'Aniline is not actually a base at all', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14211, 121707, 'Increase', 'Decrease, by further withdrawing electron density and reducing the nitrogen lone pair\'s availability', 'Have no effect', 'Convert the amine into an acid', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14212, 121708, 'Decrease', 'Increase, by donating additional electron density that partially counteracts the ring\'s electron-withdrawing resonance effect on the lone pair', 'Have no measurable effect', 'Eliminate basicity completely', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
