(14215, 121711, 'Direct reduction with LiAlH4 only', 'Hydrolysis (acidic or basic) or hydrazinolysis to release the pure primary amine from the phthalimide-protected intermediate', 'Simple heating alone', 'Oxidation with KMnO4', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14216, 121712, 'Gives 100% pure primary amine every time', 'Tends to give a mixture of primary, secondary, tertiary amines, and even quaternary ammonium salt, since each successive amine product can itself act as a nucleophile toward further alkylation', 'Produces only quaternary ammonium salts', 'Cannot proceed at all under any conditions', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14217, 121713, 'Concentrated sulfuric acid', 'Alcoholic potassium hydroxide (KOH)', 'Dilute nitric acid', 'Sodium chloride solution', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14218, 121714, 'No reaction occurs at all', 'Formation of a diazonium salt (for primary aromatic amines, stable at low temperature) or rapid evolution of nitrogen gas with alcohol formation (for primary aliphatic amines)', 'Formation of a stable amide directly', 'Formation of a secondary amine', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14219, 121715, 'Only oxygen', '-OH, -CN, -Cl, -Br, -I, -F, and even -H (via reduction), among others', 'No group at all; diazonium salts cannot be further transformed', 'Only sulfur-containing groups', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14220, 121716, 'Nucleophilic addition reaction', 'Radical substitution reaction, proceeding via a copper-mediated mechanism', 'Simple acid-base reaction', 'Elimination reaction', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
