(14262, 121808, 'Glucose and fructose', 'Two glucose units, joined by a glycosidic bond', 'Glucose and galactose', 'Two fructose units', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14263, 121809, 'Cellulose', 'Starch, stored in plant cells (like potatoes and grains) as an energy reserve', 'Chitin', 'Glycogen, which is specific to animals', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
