(14267, 121813, 'Amino group of one amino acid and the carboxyl group of another, with loss of a water molecule', 'Two amino groups of both amino acids', 'Two carboxyl groups of both amino acids', 'Side chains of both amino acids only', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14268, 121814, 'Its overall three-dimensional folded shape', 'The specific linear sequence of amino acids along the polypeptide chain', 'Only its alpha-helical regions', 'The interaction between multiple separate polypeptide subunits', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14269, 121815, 'The linear sequence of amino acids', 'Regular, repeating local folding patterns (like alpha helices and beta pleated sheets), stabilized primarily by hydrogen bonds between backbone atoms', 'Only interactions between different protein molecules', 'The complete 3D shape of a multi-subunit protein complex', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14270, 121816, 'The linear amino acid sequence only', 'The overall three-dimensional folded shape of a single polypeptide chain, stabilized by various interactions between amino acid side chains (like hydrogen bonds, disulfide bonds, hydrophobic interactions, and ionic bonds)', 'Only the interaction between multiple polypeptide chains', 'A repeating, regular secondary structure pattern only', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14271, 121817, 'The primary amino acid sequence', 'The specific arrangement and interaction of two or more separate polypeptide subunits assembled together into a single functional protein complex', 'Only a single alpha helix', 'Only the protein\'s overall net charge', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14272, 121818, 'Enhanced biological activity', 'Loss of biological activity/function, while the primary structure (peptide bond sequence) generally remains intact', 'Formation of new peptide bonds', 'No change in protein structure or function at all', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14273, 121819, 'Carbohydrates', 'Proteins (though some catalytic RNA molecules, called ribozymes, also exist)', 'Only lipids', 'Only nucleic acids exclusively', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
