(14285, 121831, 'Scurvy', 'Rickets', 'Night blindness (nyctalopia), among other vision-related problems', 'Beriberi', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14286, 121832, 'Scurvy', 'Beriberi, characterized by nerve damage, muscle weakness, and in severe cases heart problems', 'Night blindness', 'Rickets', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14287, 121833, 'Hydroxyl group and a carbonyl group only', 'Amino group (-NH2) and a carboxyl group (-COOH) attached to the same central (alpha) carbon', 'Phosphate group and a sugar', 'Two carboxyl groups only', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14288, 121834, 'Can be synthesized by the human body in sufficient quantities', 'Cannot be synthesized by the human body in sufficient quantities and must therefore be obtained through the diet', 'Are never found in any dietary protein', 'Have no biological function at all', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
