INSERT INTO `answers` (`AnswerId`, `QuestionId`, `Answer1`, `Answer2`, `Answer3`, `Answer4`, `YesNo1`, `YesNo2`, `YesNo3`, `YesNo4`, `NumStatements`, `AnsImageInd`, `MultiImageInd`, `MatchStatement1`, `MatchStatement2`, `MatchStatement3`, `MatchStatement4`, `MatchCorrect1`, `MatchCorrect2`, `MatchCorrect3`, `MatchCorrect4`) VALUES
(14291, 121837, 'They typically have a compact, globular, water-soluble structure with enzymatic function', 'They typically have elongated, thread-like structures (often rich in secondary structure like alpha helices or beta sheets) providing structural/mechanical support, and are generally insoluble in water', 'They are always composed of a single amino acid repeated infinitely', 'They have no defined secondary structure whatsoever', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14292, 121838, 'They are elongated and thread-like, providing only structural support', 'They typically fold into compact, roughly spherical (globular) shapes, are often water-soluble, and commonly perform dynamic biological functions like catalysis (enzymes) or transport (hemoglobin)', 'They have no tertiary structure at all', 'They are always insoluble in water', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14293, 121839, 'Covalent peptide bonds', 'Hydrogen bonds between complementary base pairs (A-T and G-C)', 'Ionic bonds between phosphate groups', 'Metallic bonding', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14294, 121840, 'Amino acids and peptide bonds', 'Sugar and phosphate groups, linked by phosphodiester bonds', 'Only nitrogenous bases, with no sugar or phosphate', 'Fatty acids and glycerol', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14295, 121841, 'Two entirely new strands', 'One original (parental) strand and one newly synthesized (daughter) strand', 'Two entirely original parental strands', 'No strands at all; DNA is destroyed during replication', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14296, 121842, 'Transfer RNA (tRNA)', 'Messenger RNA (mRNA)', 'Ribosomal RNA (rRNA)', 'Micro RNA (miRNA), exclusively', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14297, 121843, 'Messenger RNA (mRNA)', 'Transfer RNA (tRNA), each carrying a specific amino acid and possessing an anticodon', 'Ribosomal RNA (rRNA) exclusively', 'DNA itself', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14298, 121844, 'Messenger RNA (mRNA)', 'Transfer RNA (tRNA)', 'Ribosomal RNA (rRNA)', 'Small interfering RNA (siRNA)', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14299, 121845, 'High solubility in water', 'General insolubility (or very limited solubility) in water, but good solubility in nonpolar organic solvents', 'Composition exclusively of amino acids', 'Composition exclusively of nucleotides', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14300, 121846, 'Amino acids', 'Fatty acids, forming three ester linkages', 'Monosaccharides', 'Nucleotides', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14301, 121847, 'One or more carbon-carbon double bonds', 'No carbon-carbon double bonds (fully saturated with hydrogen), generally resulting in solid fats at room temperature', 'Only aromatic rings', 'No carbon atoms at all', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14302, 121848, 'No carbon-carbon double bonds at all', 'One or more carbon-carbon double bonds, introducing kinks in the chain that typically result in liquid oils at room temperature', 'Only single bonds and no functional groups', 'Exclusively aromatic rings', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14303, 121849, 'A simple acid-base neutralization reaction', 'A condensation (dehydration) reaction, in which a hydroxyl group of one sugar reacts with the anomeric carbon of another, releasing a water molecule', 'An oxidation-reduction reaction only', 'A reaction that adds a water molecule without releasing anything', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14304, 121850, 'Cellulose has a completely different chemical formula than starch', 'Cellulose\'s beta-1,4-glycosidic linkages allow the glucose chains to form long, straight, extensively hydrogen-bonded parallel strands (forming rigid fibers), whereas starch\'s alpha-1,4-linkages cause its chains to coil into a helical structure, less suit', 'Starch actually provides more rigidity than cellulose', 'Cellulose contains no glucose units at all', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14305, 121901, 'Melting point of a solid', 'Unknown concentration of a solution by reacting it with a solution of known concentration (titrant), typically using an indicator to signal the endpoint', 'Boiling point of a liquid', 'Molecular structure of a compound directly', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14306, 121902, 'A redox indicator', 'A pH indicator (like phenolphthalein or methyl orange), which changes color at a specific pH range near the equivalence point', 'A precipitation indicator only', 'No indicator is ever needed', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14307, 121903, 'Yellow', 'Pink/magenta', 'Blue', 'Green', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14308, 121904, 'Blue', 'Yellow', 'Green', 'Colorless', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14309, 121905, 'The indicator changes color permanently', 'The moles of acid exactly equal the moles of base (or more generally, reactants are present in exact stoichiometric proportions)', 'The solution becomes completely colorless', 'The reaction stops completely and irreversibly', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14310, 121906, 'The exact theoretical equivalence point, always identical to it', 'The point at which the indicator visibly changes color, signaling the experimenter to stop adding titrant — ideally very close to, but not always exactly identical to, the true equivalence point', 'The point at which the solution boils', 'The point at which no more reaction is possible ever', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14311, 121907, 'With an unknown concentration', 'Whose concentration is precisely and accurately known', 'That has no solute dissolved in it', 'That changes concentration constantly during use', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14312, 121908, 'Highly hygroscopic (absorbing moisture readily)', 'Available in high purity, stable, non-hygroscopic, and have a reasonably high molar mass to minimize weighing errors', 'Unstable and prone to decomposition', 'Impossible to weigh accurately', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14313, 121909, 'Only acids', 'Bases (like NaOH) as well as oxidizing agents (like KMnO4) in redox titrations', 'Only indicators', 'Only water', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14314, 121910, 'KMnO4 has no color at all', 'KMnO4 itself is intensely purple/pink colored, and this color disappears as it is reduced, but a slight excess produces a persistent faint pink color signaling the endpoint (self-indicating)', 'The reaction produces no color change whatsoever', 'A separate indicator is always required regardless', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14315, 121911, 'Using a simple mercury thermometer directly immersed in the bulk solid', 'Using a melting point apparatus, where a small amount of finely powdered sample in a capillary tube is gradually heated while observing the temperature at which melting begins and completes', 'Using a pH meter', 'Using a spectrophotometer', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14316, 121912, 'The presence of significant impurities', 'A relatively pure compound, since impurities typically broaden and lower the observed melting point range', 'Nothing about purity at all', 'That the compound is actually a liquid at room temperature', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14317, 121913, 'Melting point determination', 'The bromine water (or Baeyer\'s) test, which decolorizes in the presence of unsaturation (multiple bonds)', 'Simple titration with HCl', 'Measuring density alone', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14318, 121914, 'Alcohols specifically', 'A reducing sugar or an aldehyde group, based on the compound\'s ability to reduce the respective metal ion reagent (Ag+ or Cu2+)', 'Halogens exclusively', 'Amines exclusively', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14319, 121915, 'Tollens\' test', 'Lucas\' test, using concentrated HCl and anhydrous ZnCl2, based on the differing rates of cloudiness (alkyl chloride formation)', 'Fehling\'s test', 'Litmus paper test', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14320, 121916, 'Tollens\' test', 'Addition of sodium bicarbonate (NaHCO3) solution, observing brisk effervescence (CO2 gas evolution) as a positive indication of a carboxylic acid', 'Lucas\' test', 'Iodoform test exclusively', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14321, 121917, 'The pH of a solution', 'Heat changes (absorbed or released) during a physical or chemical process', 'The concentration of a solution via titration', 'The refractive index of a liquid', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14322, 121918, 'Concentration of a specific ion other than H+', 'Hydrogen ion concentration (acidity/basicity) of a solution, expressed as pH', 'Boiling point of a liquid', 'Melting point of a solid', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14323, 121919, 'pH directly', 'Electrical conductivity, related to the concentration and mobility of ions present in the solution', 'Melting point', 'Optical rotation', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14324, 121920, 'Color only', 'Electrical conductivity as titrant is added, typically observing a distinct change in slope at the equivalence point', 'Temperature exclusively', 'Density only', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14325, 121921, 'A burette provides no particular advantage over a beaker', 'A burette allows precise, controlled, incremental addition of titrant with accurate volume measurement (readable to a fraction of a mL), essential for determining the exact volume needed to reach the endpoint', 'A burette is only used for solids, never liquids', 'A burette automatically detects the endpoint without any indicator', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14326, 121922, 'Measure the temperature of a solution', 'Accurately and precisely measure and transfer a specific, fixed volume of a solution (like the analyte) into a titration flask', 'Measure electrical conductivity', 'Determine melting point', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14327, 121923, 'Measure exact volumes directly', 'Swirl/mix the solution thoroughly without spilling, while the titrant is being added from the burette above', 'Heat the solution to boiling', 'Determine pH directly without any meter', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14328, 121924, 'A blank titration has no useful purpose', 'A blank titration accounts for and corrects any titrant consumed by reactions with reagents/indicator alone (rather than the analyte), improving the accuracy of the final calculated result', 'A blank titration replaces the need for any indicator', 'A blank titration is only used to calibrate a pH meter', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14329, 121925, 'Normality is identical to molarity in every situation', 'Normality expresses concentration in terms of gram equivalents per litre, accounting for the specific number of reactive units (like replaceable H+ ions or electrons transferred) per formula unit, which can differ from simple molarity depending on the rea', 'Normality only applies to pure water', 'Normality is always exactly double the molarity', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14330, 121926, 'Highly acidic (pH well below 7)', 'Neutral (pH close to 7), since the salt formed does not undergo significant hydrolysis', 'Highly basic (pH well above 7)', 'Undefined, with no expected value', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14331, 121927, 'Exactly 7 (neutral)', 'Greater than 7 (basic), since the salt formed (conjugate base of the weak acid) undergoes hydrolysis to produce a basic solution', 'Less than 7 (acidic)', 'Impossible to determine or estimate', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14332, 121928, 'Greater than 7 (basic)', 'Less than 7 (acidic), since the salt formed (conjugate acid of the weak base) undergoes hydrolysis to produce an acidic solution', 'Exactly 7 (neutral)', 'Impossible to determine', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14333, 121929, 'Any indicator works equally well for any titration, regardless of pH range', 'An indicator whose color-change range does not closely match the actual pH at the equivalence point will cause the observed endpoint to differ significantly from the true equivalence point, introducing significant titration error', 'Indicators have no effect on titration accuracy at all', 'The indicator\'s cost is the only relevant consideration', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14334, 121930, 'Phenolphthalein works better in all situations regardless of pH', 'The equivalence point of a strong acid-weak base titration is acidic (below pH 7), matching methyl orange\'s transition range, while phenolphthalein\'s transition range (8.2-10) is too basic and would cause a significant titration error in this case', 'Methyl orange only works with strong bases', 'Both indicators are always interchangeable with no consequence', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14335, 121931, 'Measuring the volume of titrant needed to reach an endpoint', 'Precipitating the analyte (or a compound containing it) in a pure, easily filterable form, then drying and precisely weighing this precipitate to determine the original analyte\'s quantity', 'Measuring the color intensity of a solution only', 'Measuring the melting point of the analyte', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14336, 121932, 'The precipitate should be highly soluble in the reaction mixture', 'The precipitate should be sufficiently insoluble (minimizing loss during filtration), pure, and in a form that can be easily filtered, washed, and weighed without decomposition', 'No washing of the precipitate is ever necessary', 'The precipitate\'s exact chemical formula is irrelevant to the calculation', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14337, 121933, 'To heat samples to very high temperatures', 'To store dried samples/precipitates in a moisture-free environment (using a desiccant like silica gel), preventing reabsorption of atmospheric water vapor before final weighing', 'To dissolve samples in water', 'To measure the pH of a solution', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14338, 121934, 'The measured mass would be artificially low', 'The measured mass could be artificially high, due to residual soluble impurities/mother liquor solutes remaining adsorbed on/with the precipitate', 'No error would occur at all', 'The precipitate would completely dissolve', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14339, 121935, 'A rough titration is unnecessary and wastes materials', 'A rough titration provides an approximate idea of the volume of titrant needed to reach the endpoint, allowing the chemist to add titrant more quickly in early precise trials and then more cautiously (dropwise) as the estimated endpoint approaches, improv', 'A rough titration always gives the exact, final, precise answer needed', 'A rough titration replaces the need for an indicator entirely', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14340, 121936, 'Titre values that differ wildly from each other with no consistency', 'Titre (volume) readings from repeated trials that agree closely with each other (typically within about 0.1 mL), indicating good precision and reliability of the measurement', 'A single titration performed only once, with no repetition', 'Titre values measured using different indicators each time', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14341, 121937, 'Rinsing has no practical importance and can be skipped', 'Rinsing with the titrant removes any residual water (or previous solution) inside the burette that could otherwise dilute the titrant and introduce a systematic error into the measured volume/concentration', 'Rinsing with titrant contaminates the burette and should never be done', 'Water residue in a burette has no effect on titration accuracy', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14342, 121938, 'A pipette can measure any volume, just like a burette', 'A volumetric pipette is calibrated and marked for one specific, precise volume only, making it ideal for accurately delivering that fixed amount repeatedly, whereas a burette\'s graduated markings allow variable, adjustable volume delivery as needed during', 'Pipettes cannot hold any liquid at all', 'Burettes can only measure one fixed volume, like pipettes', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14343, 121939, 'Reading from any angle gives identical results', 'Reading at eye level from the bottom of the meniscus curve minimizes parallax error, ensuring an accurate and reproducible volume measurement', 'The meniscus shape has no effect on volume reading accuracy', 'Only the top of the meniscus should ever be read, regardless of angle', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14344, 121940, 'A systematic error occurs randomly and unpredictably each time', 'A systematic error consistently affects all measurements in the same direction (e.g., a miscalibrated burette consistently reading slightly high), and can often be identified and corrected (e.g., via a blank titration or calibration), unlike random errors', 'Systematic errors cannot be identified or corrected under any circumstances', 'There is no meaningful difference between systematic and random errors', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14345, 121941, 'A single trial always gives a perfectly accurate result', 'Repeating the titration helps identify and minimize random errors, allowing an average (mean) of concordant results to provide a more reliable, precise final value than any single measurement alone', 'Repetition introduces additional errors and should be avoided', 'Only the first titration trial performed is ever considered valid', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14346, 121942, 'To dilute the titrant significantly before use', 'To rinse down any droplets of solution clinging to the walls of the flask or burette tip, ensuring all reacted material is included in the measurement and washing away any splashed titrant/analyte for accurate results', 'To measure the exact volume of titrant delivered', 'To change the indicator\'s color permanently', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14347, 121943, 'NaOH is completely insoluble in water', 'NaOH is highly hygroscopic (readily absorbing atmospheric moisture) and also reacts with atmospheric carbon dioxide, both of which alter its effective mass/purity, making it unsuitable as a primary standard despite being easy to weigh', 'NaOH has no measurable molar mass', 'NaOH reacts explosively with air at room temperature', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14348, 121944, 'Simply assuming its concentration without any verification', 'Titrating the solution against a known primary standard solution (or substance) to accurately determine its actual concentration', 'Heating the solution until it evaporates completely', 'Measuring only its color intensity', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14349, 121945, 'Potassium dichromate has no oxidizing properties at all', 'Potassium dichromate is available in a very high, stable purity suitable as a primary standard directly, and its solutions are more stable over time (less prone to decomposition) compared to potassium permanganate solutions, which tend to slowly decompose', 'Potassium permanganate is always the better choice in every situation with no exceptions', 'Potassium dichromate cannot be used in any titration', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14350, 121946, 'To make the glassware colorful', 'To remove any residual contaminants, dust, or previous solution traces that could otherwise introduce errors by altering the concentration or reacting with reagents in subsequent use', 'Rinsing has no effect on measurement accuracy', 'To increase the glassware\'s exact calibrated volume permanently', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14351, 121947, 'A graduated cylinder is always more accurate than a volumetric flask', 'A volumetric flask is calibrated to contain one precise, specific volume (marked with a single calibration line), providing much higher precision for preparing exact solution volumes than the broader, less precise gradations of a graduated cylinder', 'Volumetric flasks cannot hold any liquid', 'Graduated cylinders are used exclusively for solids', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14352, 121948, 'To cool and condense vapors of a volatile reaction mixture back into the reaction flask, allowing prolonged heating without significant loss of volatile reactants/solvent', 'To measure the temperature of the reaction', 'To filter solid impurities from the reaction mixture', 'To measure the pH of the reaction mixture', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14353, 121949, 'To increase the water content of an organic solution', 'To remove residual trace water from an organic solution (typically after an aqueous extraction step), yielding a drier product for subsequent purification steps like distillation or crystallization', 'To dissolve the organic product completely into water', 'To change the color of the organic solution', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14354, 121950, 'A rough titre is the only value ever needed for the final report', 'A rough titre gives an approximate endpoint volume, letting the analyst add titrant quickly at first in subsequent precise trials and then dropwise near the expected endpoint, saving time while still achieving precise, concordant final readings', 'Rough titres are always identical to precise titres with no practical difference', 'Performing a rough titration is prohibited in standard laboratory practice', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
