INSERT INTO `answers` (`AnswerId`, `QuestionId`, `Answer1`, `Answer2`, `Answer3`, `Answer4`, `YesNo1`, `YesNo2`, `YesNo3`, `YesNo4`, `NumStatements`, `AnsImageInd`, `MultiImageInd`, `MatchStatement1`, `MatchStatement2`, `MatchStatement3`, `MatchStatement4`, `MatchCorrect1`, `MatchCorrect2`, `MatchCorrect3`, `MatchCorrect4`) VALUES
(15506, 800382, 'It indicates the model needs a larger context window', 'It indicates the pre-launch evaluation lacked adversarial or red-team style testing; standard evaluation prompts alone often miss vulnerabilities that only surface under deliberate, creative probing', 'It indicates the retrieval index is out of date', 'It indicates the evaluation dataset was too large', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15507, 800383, 'Switch to a larger, more expensive language model without changing chunking', 'Increase the number of retrieved chunks without changing their size', 'Reduce the chunk size (with appropriate overlap) so retrieved chunks are more focused on specific, relevant content', 'Disable the vector index and rely on keyword search only', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15508, 800384, 'Fine-tuning, because it is cheaper and faster to update daily than RAG', 'Fine-tuning, because it eliminates the need for any retrieval infrastructure and updates itself', 'Neither -- always default to the largest available model regardless of update frequency', 'RAG, because it retrieves up-to-date information at query time without needing to retrain the model whenever the knowledge base changes', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15509, 800385, 'Implementing response caching for identical or semantically similar prompts', 'Increasing the provisioned throughput units regardless of traffic pattern', 'Switching every request to the largest available model', 'Disabling content safety filters', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15510, 800386, 'Prompt engineering always produces a smaller model file than fine-tuning', 'Prompt engineering requires no model retraining and is faster to iterate, but may be less consistent for highly specialized or nuanced tasks than a fine-tuned model', 'Prompt engineering guarantees higher accuracy than fine-tuning in every case', 'Prompt engineering requires GPU training clusters while fine-tuning does not', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15511, 800387, 'Purchasing maximum provisioned throughput permanently sized for peak traffic', 'Using only pay-as-you-go with no capacity planning at all', 'A combination of a smaller provisioned throughput baseline plus pay-as-you-go (consumption) overflow capacity for spikes', 'Disabling autoscaling entirely to keep costs predictable', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15512, 800388, 'Decreasing the embedding vector dimensionality', 'Switching to a smaller, faster embedding model with lower accuracy', 'Reducing the context window sent to the model', 'Increasing the number of top-k retrieved chunks passed to the model as context', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15513, 800389, 'Dynamically directing requests to different models, such as a smaller or cheaper model for simple queries and a larger model for complex ones, based on request characteristics', 'Physically routing network cables between datacenters', 'Randomly selecting any available model regardless of task', 'Always using the most expensive model to guarantee quality', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15514, 800390, 'Increase the language model\'s temperature setting', 'Switch to or fine-tune an embedding model better suited to the domain, such as a domain-specific or higher-quality embedding model', 'Reduce the number of documents in the index to speed up search', 'Disable retrieval and rely purely on the model\'s parametric knowledge', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15515, 800391, 'Always requesting the maximum possible output token length', 'Adding additional unnecessary retrieval steps to every request', 'Streaming the model\'s response tokens to the client as they are generated instead of waiting for the full completion', 'Increasing the number of retries on every failed request without backoff', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15516, 800392, 'Increasing the model\'s max output tokens', 'Adding more few-shot examples to improve accuracy regardless of cost', 'Switching to a larger context window model without changing prompt length', 'Shortening the system prompt and few-shot examples where possible, or using prompt caching features if available, to reduce repeated token overhead', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15517, 800393, 'Whether current failures are due to context being cut off at chunk boundaries, favoring more overlap, versus poor semantic matching during retrieval, favoring a better embedding model', 'Always choose higher dimensionality regardless of the failure pattern, since it is universally better', 'Always choose more overlap regardless of the failure pattern, since it is cheaper', 'Neither change affects RAG answer quality, so pick based on cost alone', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
