(16410, 801586, 'A UNION of the two result sets with duplicates removed only', 'Sorting purely by full-text rank and ignoring vector distance', 'Sorting purely by vector distance and ignoring full-text rank', 'Combining the full-text relevance score and vector similarity score with a weighting formula', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16411, 801587, 'Store the API key using a database scoped credential rather than plain text in the procedure', 'Embed the API key directly in the procedure body', 'Email the API key to all developers', 'Store the API key in a comment at the top of the script', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16412, 801588, 'Nothing needs to change; old vectors remain compatible', 'All existing documents must be re-embedded and the vector column/index redefined to match the new dimensionality', 'Only the vector index needs to be dropped; embeddings stay the same', 'Only the newest documents need embeddings; older ones are fine as is', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16413, 801589, 'It replaces the language model entirely with a rules engine', 'It increases the model\'s training data permanently', 'It supplies relevant, factual retrieved context so the response is grounded in real data rather than relying solely on the model\'s trained knowledge', 'It encrypts the model\'s output', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16414, 801590, 'JSON_VALUE', 'STRING_SPLIT', 'OPENJSON', 'VECTOR_DISTANCE (dot-product metric option)', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `answers` (`AnswerId`, `QuestionId`, `Answer1`, `Answer2`, `Answer3`, `Answer4`, `YesNo1`, `YesNo2`, `YesNo3`, `YesNo4`, `NumStatements`, `AnsImageInd`, `MultiImageInd`, `MatchStatement1`, `MatchStatement2`, `MatchStatement3`, `MatchStatement4`, `MatchCorrect1`, `MatchCorrect2`, `MatchCorrect3`, `MatchCorrect4`) VALUES
(16415, 801591, 'Combine a WHERE filter on metadata with the vector similarity ORDER BY/TOP N pattern', 'Ignore metadata and rely solely on vector distance', 'Store metadata in a separate, unrelated database with no join', 'Perform the metadata filter only after returning all rows to the client application', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16416, 801592, 'Azure Data Factory', 'Azure OpenAI Service (Azure AI Foundry)', 'Azure Traffic Manager', 'Azure Bastion', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16417, 801593, 'Send all 500,000 rows in a single request', 'Disable the embedding endpoint\'s rate limits', 'Process rows in smaller batches with controlled concurrency and retry/backoff logic', 'Store the descriptions as images instead of text', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16418, 801594, 'TOP N has no relationship to vector search', 'TOP N replaces the need for an ORDER BY clause', 'TOP N can only be used with full-text search', 'TOP N combined with ORDER BY on a computed VECTOR_DISTANCE value returns the N nearest rows', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16419, 801595, 'The embedding model must be multilingual so semantically similar text across languages sits close together in vector space', 'The embedding model must only support English and translate later', 'The chunk size must be reduced to a single word', 'The vector index type has no effect on language support', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16420, 801596, 'Reducing the chunk size to one character', 'Adding hybrid search that combines keyword/full-text matching with vector similarity', 'Removing the vector index entirely', 'Switching to a smaller embedding model', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16421, 801597, 'To guarantee the model never makes a mistake', 'To permanently delete unused chunks', 'To keep the prompt within the context window and reduce cost/latency while supplying the most relevant context', 'To increase the dimensionality of the embeddings', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16422, 801598, 'It reduces the storage size of the VECTOR column', 'It removes the need to ever recompute embeddings', 'It guarantees exact nearest-neighbor results', 'It makes cosine similarity and dot-product calculations equivalent, simplifying distance comparisons', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16423, 801599, 'A RAG architecture that retrieves policy document chunks and instructs the model to answer only from the provided context', 'Fine-tuning a public model on the general internet with no retrieval', 'Allowing the model to answer purely from its pretrained knowledge', 'Removing the database entirely and hardcoding all answers', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16424, 801600, 'Chunk size should always be as small as a single sentence regardless of content', 'Chunk size should balance retaining enough context to be meaningful against staying small enough for precise retrieval and prompt limits', 'Chunk size has no effect on retrieval quality', 'Chunk size should always equal the entire document', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16425, 801601, 'Improves recall for exact terms/identifiers alongside semantic matches', 'Eliminates the need to generate embeddings entirely', 'Combines semantic relevance with precise keyword matching', 'Guarantees zero query latency', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16426, 801602, 'JSON_VALUE', 'JSON_QUERY', 'OPENJSON', 'PARSENAME', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16427, 801603, 'Stored procedure', 'Trigger', 'Scalar function', 'Foreign key constraint', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16428, 801604, 'Stores data column-wise', 'Provides high compression for large analytical tables', 'Is the default index type for OLTP primary keys', 'Eliminates the need for any other indexes on the table', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16429, 801605, 'Defining a recursive query that references itself', 'Simplifying a complex query by breaking it into named steps', 'Permanently storing data across sessions', 'Replacing the need for indexes entirely', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16430, 801606, 'The table contains millions of rows and similarity queries scan the whole table', 'Query latency for nearest-neighbor searches must be minimized', 'The table only ever stores 10 rows of reference data', 'The column is never queried for similarity', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16431, 801607, 'Transparent Data Encryption (TDE)', 'Always Encrypted', 'Dynamic data masking', 'Clustered index', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16432, 801608, 'It is enforced automatically by the database engine using a security predicate', 'It requires application code to add WHERE clauses manually to every query', 'It can filter rows for SELECT as well as restrict INSERT/UPDATE/DELETE operations', 'It encrypts the underlying row data', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16433, 801609, 'Full backup', 'Differential backup', 'Transaction log backup', 'Snapshot rollback backup', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16434, 801610, 'Enables repeatable, version-controlled schema deployments across environments', 'Automatically detects and resolves all application-level bugs', 'Can generate an incremental upgrade script by comparing target and source schemas', 'Eliminates the need for any testing before production deployment', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16435, 801611, 'Creating a covering index that includes needed columns', 'Updating outdated statistics', 'Rewriting non-sargable predicates to be sargable', 'Increasing MAXDOP to an arbitrarily high value on every server regardless of workload', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16436, 801612, 'It allows centrally managed identities to authenticate without a separate SQL login and password', 'It supports multi-factor authentication', 'It is the only authentication method Azure SQL supports', 'It automatically encrypts all data at rest', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16437, 801613, 'Generate an embedding for the user\'s query', 'Retrieve the most similar stored chunks using vector search', 'Augment the prompt with retrieved context before calling the language model', 'Permanently delete the source documents after each query', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16438, 801614, 'Cosine', 'Euclidean', 'Dot product', 'Levenshtein', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16439, 801615, 'It combines keyword/full-text search with vector similarity search', 'It requires discarding the vector index once keyword search is added', 'It can improve recall for exact terms like product codes or identifiers', 'It guarantees identical results to pure vector search', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16440, 801616, 'Calling an embedding model endpoint to generate a vector for new text', 'Calling a chat completion endpoint to summarize retrieved rows', 'Replacing the SQL Server transaction log', 'Directly modifying the database\'s system catalog views', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16441, 801617, 'Chunk size affects retrieval precision', 'Overlapping chunks can help preserve context across boundaries', 'Chunking is unnecessary for very large documents since embeddings have no length limitations', 'Chunk boundaries should ideally respect semantic units, like paragraphs or sections', NULL, NULL, NULL, NULL, 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16442, 801618, 'JSON_VALUE returns a scalar value from a JSON string at the specified path.', 'OPENJSON can convert a JSON array into a set of relational rows.', 'FOR JSON is used to parse JSON text into a table, not to produce JSON output.', NULL, 'Y', 'Y', 'N', NULL, 3, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16443, 801619, 'A view stores a saved SELECT statement and does not duplicate the underlying table data.', 'A stored procedure cannot accept input parameters.', NULL, NULL, 'Y', 'N', NULL, NULL, 2, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16444, 801620, 'The VECTOR data type stores a fixed-length array of floating-point numbers.', 'A vector index in SQL Server 2025 always returns exact nearest-neighbor results with no approximation.', 'VECTOR_DISTANCE can be used to compute similarity between two embeddings of the same dimensionality.', 'Vector columns can only be created in Azure SQL and are not available in SQL Server 2025.', 'Y', 'N', 'Y', 'N', 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16445, 801621, 'A temporal (system-versioned) table automatically retains history of row changes in a linked history table.', 'A trigger executes automatically in response to DML events without being explicitly called by the application.', 'A scalar user-defined function can only be used in the FROM clause of a query, never in a SELECT list.', NULL, 'Y', 'Y', 'N', NULL, 3, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16446, 801622, 'A columnstore index is generally well suited to large analytical fact tables queried with aggregations.', 'A filtered index always indexes every row of the table regardless of any WHERE predicate.', NULL, NULL, 'Y', 'N', NULL, NULL, 2, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16447, 801623, 'Storing an embedding as a native VECTOR column enables the use of built-in vector indexes and distance functions.', 'JSON columns are the only possible way to add flexible, category-specific attributes to a product catalog table.', 'A computed column can be persisted and indexed to improve query performance on a derived expression.', NULL, 'Y', 'N', 'Y', NULL, 3, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16448, 801624, 'Transparent Data Encryption (TDE) encrypts data files at rest and is transparent to the application.', 'Always Encrypted allows the database engine itself to view the plaintext of protected columns.', 'Dynamic data masking changes the actual data stored on disk to a masked value.', NULL, 'Y', 'N', 'N', NULL, 3, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16449, 801625, 'Row-level security is enforced automatically by the database engine using a security predicate function.', 'Row-level security requires the application to add WHERE clauses manually to filter rows for each user.', NULL, NULL, 'Y', 'N', NULL, NULL, 2, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16450, 801626, 'Query Store captures the history of execution plans and runtime statistics over time.', 'A missing index under a selective WHERE predicate typically causes a table or index scan in the execution plan.', 'Updating statistics can never change the execution plan chosen by the optimizer.', 'A covering index includes all columns needed by a query so the base table does not need to be accessed.', 'Y', 'Y', 'N', 'Y', 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16451, 801627, 'A DACPAC packages a database schema as a versioned, deployable artifact.', 'Deploying a DACPAC always drops and recreates the entire target database, deleting all existing data.', 'A SQL database project can be stored in source control and built as part of a CI/CD pipeline.', NULL, 'Y', 'N', 'Y', NULL, 3, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16452, 801628, 'The full recovery model, combined with regular transaction log backups, supports point-in-time restore.', 'A differential backup captures all data in the database regardless of what has changed since the last full backup.', NULL, NULL, 'Y', 'N', NULL, NULL, 2, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16453, 801629, 'SQL Server Audit can record login events and permission changes to a durable log for compliance.', 'DENY permission on a principal is overridden whenever that principal is also granted the same permission through a role.', 'Following least privilege means granting a service account only the specific permissions it needs, not broad administrative rights.', NULL, 'Y', 'N', 'Y', NULL, 3, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16454, 801630, 'In a RAG pipeline, retrieved document chunks are added to the prompt to help ground the language model\'s response.', 'RAG eliminates the need for a language model altogether, since the database returns the final answer directly.', 'Vector similarity search is commonly used to identify the most relevant chunks to retrieve in a RAG pipeline.', NULL, 'Y', 'N', 'Y', NULL, 3, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16455, 801631, 'An embedding is a numeric vector representation of text (or other data) that captures semantic meaning.', 'Two embeddings generated by different, incompatible embedding models are always directly comparable with the same distance function.', NULL, NULL, 'Y', 'N', NULL, NULL, 2, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16456, 801632, 'Hybrid search combines keyword-based full-text search with vector similarity search.', 'A vector index guarantees perfectly exact nearest-neighbor results in all cases.', 'Cosine similarity is commonly used to compare the semantic similarity of two text embeddings.', 'Hybrid search removes the need to ever generate embeddings for stored content.', 'Y', 'N', 'Y', 'N', 4, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16457, 801633, 'sp_invoke_external_rest_endpoint allows T-SQL code to call an external REST API such as an Azure OpenAI endpoint.', 'Credentials used to call an external AI endpoint from T-SQL should be stored as a database scoped credential rather than hard-coded in plain text.', 'Calling an external embedding model from T-SQL requires rewriting the database engine in a different programming language.', NULL, 'Y', 'Y', 'N', NULL, 3, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16458, 801634, 'The dimensionality of vectors generated by an embedding model must match the dimension defined on the VECTOR column storing them.', 'Document chunk size has no effect on the quality or precision of retrieval in a RAG solution.', NULL, NULL, 'Y', 'N', NULL, NULL, 2, 'N', 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16459, 801635, 'JSON_VALUE', 'JSON_QUERY', 'OPENJSON', NULL, NULL, NULL, NULL, NULL, 3, 'N', 'N', 'Extracts a scalar value from a JSON string at a given path', 'Extracts an object or array from a JSON string at a given path', 'Converts JSON text into a set of rows and columns', NULL, 1, 2, 3, NULL),
(16460, 801636, 'Stored procedure', 'View', 'Trigger', 'Table-valued function', NULL, NULL, NULL, NULL, 4, 'N', 'N', 'A precompiled batch of T-SQL that accepts parameters and can return result sets', 'A saved SELECT statement that behaves like a virtual table', 'Executes automatically in response to INSERT, UPDATE, or DELETE events', 'Returns a table result and can be referenced in a FROM clause like a parameterized view', 1, 2, 3, 4),
(16461, 801637, 'Columnstore index', 'Filtered index', NULL, NULL, NULL, NULL, NULL, NULL, 2, 'N', 'N', 'Stores data column-wise with high compression, well suited to analytical aggregation queries', 'Indexes only the subset of rows matching a WHERE predicate', NULL, NULL, 1, 2, NULL, NULL),
(16462, 801638, 'Common table expression (CTE)', 'Window function', 'MERGE', NULL, NULL, NULL, NULL, NULL, 3, 'N', 'N', 'Defines a named temporary result set that can reference itself recursively', 'Computes a running total or rank across a set of related rows without collapsing the result with GROUP BY', 'Performs INSERT, UPDATE, and DELETE in a single statement by comparing a target table to a source', NULL, 1, 2, 3, NULL),
(16463, 801639, 'SQL database in Microsoft Fabric', 'Azure SQL Database', 'SQL Server 2025', 'Computed column', NULL, NULL, NULL, NULL, 4, 'N', 'N', 'Integrates with OneLake so data can be queried via T-SQL across the Fabric platform', 'A fully managed PaaS relational database service in Azure with built-in high availability', 'The installable version of SQL Server that introduces native VECTOR support', 'A column whose value is automatically derived from an expression over other columns', 1, 2, 3, 4),
(16464, 801640, 'FOR JSON AUTO', 'FOR JSON PATH', NULL, NULL, NULL, NULL, NULL, NULL, 2, 'N', 'N', 'Derives the JSON nesting structure automatically based on the SELECT\'s table structure', 'Gives explicit control over property names and nesting using dotted aliases', NULL, NULL, 1, 2, NULL, NULL),
(16465, 801641, 'Always Encrypted', 'Transparent Data Encryption (TDE)', 'Row-level security', NULL, NULL, NULL, NULL, NULL, 3, 'N', 'N', 'Protects sensitive data even from users with database admin access', 'Encrypts the database files at rest without application changes', 'Restricts which rows a given user is permitted to query', NULL, 1, 2, 3, NULL),
(16466, 801642, 'GRANT', 'DENY', 'REVOKE', 'Ownership chaining', NULL, NULL, NULL, NULL, 4, 'N', 'N', 'Gives a principal a specified permission', 'Explicitly blocks a permission, overriding any grant through role membership', 'Removes a previously granted or denied permission, returning to no explicit setting', 'Allows a procedure to access objects owned by the same principal without the caller needing direct permission on them', 1, 2, 3, 4),
(16467, 801643, 'Full backup', 'Differential backup', NULL, NULL, NULL, NULL, NULL, NULL, 2, 'N', 'N', 'Captures the entire database at a point in time', 'Captures only the changes since the last full backup', NULL, NULL, 1, 2, NULL, NULL),
