(4, 1, 'JoSAA Counselling 2027\n(IITs+NITs+IIITs+GFTIs)', 'JoSAA Counselling', 'NOT an exam - centralised seat allocation using JEE Main + JEE Advanced ranks', 'Jun-Jul 2027', 'Jun 2027', 'Jul 2027', '2027-07-15', 'https://josaa.nic.in', 'Free', '23 IITs · 31 NITs · 26 IIITs · 40 GFTIs - 120+ premier govt institutions. Non-JoSAA = colleges using JEE score with own counselling.', 'CRITICAL', 'Register on josaa.nic.in after JEE results. Choice filling strategy is critical.', 'N', 'Y', 0, 4, '2026-08-06 07:29:22', '2026-08-06 07:29:22', NULL, NULL),
(5, 1, 'JAC Delhi Counselling 2027\n(DTU+NSUT+IGDTUW+IIIT Delhi)', 'JAC Delhi', 'NOT an exam - uses JEE Main rank. Separate from JoSAA.', '~Jul 2027', 'Jul 2027', 'Jul 2027', '2027-07-31', 'https://jacdelhi.admissions.nic.in', 'Free', 'DTU (Delhi Technological University) · NSUT · IGDTUW · IIIT Delhi - excellent Delhi govt engineering colleges.', 'HIGH', 'Apply on JAC Delhi portal SEPARATELY from JoSAA - different portal, same JEE Main rank.', 'N', 'Y', 0, 5, '2026-08-06 07:29:22', '2026-08-06 07:29:22', NULL, NULL),
