(1310, 25, NULL, NULL, 30, '', '2', 'Y', 1, 'images/Java/30/1310.PNG', 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 0, NULL, NULL, NULL),
(1311, 25, NULL, NULL, 30, '', '1', 'Y', 1, 'images/Java/30/1311.PNG', 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 0, NULL, NULL, NULL),
