(5206, 103, NULL, NULL, 3106, 'Who composed the music for Sholay (1975), including the blockbuster song \'Mehbooba Mehbooba\'?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'R.D. Burman composed the entire Sholay soundtrack.', NULL, NULL),
(5207, 103, NULL, NULL, 3106, '\'Mehbooba Mehbooba\' from Sholay was unusually sung by the composer himself. Who sang it?', '3', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'R.D. Burman himself sang \'Mehbooba Mehbooba,\' picturised on Helen.', NULL, NULL),
(5208, 103, NULL, NULL, 3106, 'In Sholay, which actor played Veeru, Amitabh Bachchan\'s on-screen partner-in-crime?', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Dharmendra played Veeru opposite Amitabh Bachchan\'s Jai.', NULL, NULL);
INSERT INTO `questions` (`QuestionId`, `SubjectInfoId`, `ChapterInfoId`, `CaseStudyId`, `ExamInfoId`, `QuestionDesc`, `CorrectAnswer`, `ImageInd`, `NumofImages`, `ImageLoc`, `OperatorInd`, `Complexity`, `IsActive`, `IsDeleted`, `DeletedAt`, `DeletedBy`, `QuestionType`, `ExpectedAnswerCount`, `Explanation`, `LinkedFromQuestionId`, `TranslatedFromQuestionId`) VALUES
(5209, 103, NULL, NULL, 3106, 'Which 1975 Yash Chopra film features the iconic line \'Mere paas maa hai,\' delivered by Shashi Kapoor\'s character in response to Amitabh Bachchan?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The line is from Deewaar (1975), one of Hindi cinema\'s most quoted dialogues.', NULL, NULL),
(5210, 103, NULL, NULL, 3106, 'Deewaar (1975), like Zanjeer, was written by which screenwriting duo?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Salim-Javed also wrote Deewaar.', NULL, NULL),
(5211, 103, NULL, NULL, 3106, 'Which 1977 Manmohan Desai blockbuster features Amitabh Bachchan, Vinod Khanna, and Rishi Kapoor as three brothers separated in childhood and raised in different faiths?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Amar Akbar Anthony (1977) is one of the biggest hits of the decade.', NULL, NULL),
(5212, 103, NULL, NULL, 3106, 'In Amar Akbar Anthony (1977), Amitabh Bachchan played which of the three title characters?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Bachchan played Anthony, the Christian-raised brother who runs a bar.', NULL, NULL),
(5213, 103, NULL, NULL, 3106, 'Which 1978 crime thriller, directed by Chandra Barot, saw Amitabh Bachchan play a double role as a gangster and his lookalike?', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Don (1978) cast Bachchan in a memorable double role.', NULL, NULL),
(5214, 103, NULL, NULL, 3106, 'The hit song \'Khaike Paan Banaraswala\' from Don (1978) was sung by:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Kishore Kumar sang this famous song, picturised on Amitabh Bachchan.', NULL, NULL),
(5215, 103, NULL, NULL, 3106, 'Which composer duo scored the music for Don (1978)?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Kalyanji-Anandji also composed the Don soundtrack.', NULL, NULL),
(5216, 103, NULL, NULL, 3106, 'Which actress played the female lead alongside Amitabh Bachchan in Don (1978)?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Zeenat Aman played the female lead in Don.', NULL, NULL),
(5217, 103, NULL, NULL, 3106, 'Which 1978 Yash Chopra film starred Amitabh Bachchan as a man seeking revenge against the father who had once abandoned him and his mother?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Trishul (1978) built its story around this revenge plot.', NULL, NULL),
(5218, 103, NULL, NULL, 3106, 'Which 1978 film paired Amitabh Bachchan with Rekha in the story of a poor orphan\'s rise to wealth and power?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Muqaddar Ka Sikandar (1978) was a major hit for the pair.', NULL, NULL),
(5219, 103, NULL, NULL, 3106, 'Which 1979 drama, inspired by a real-life mining tragedy, starred Amitabh Bachchan and Shashi Kapoor as coal miners?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Kaala Patthar (1979) drew on the Chasnala mining disaster.', NULL, NULL),
(5220, 103, NULL, NULL, 3106, 'Which 1971 Hrishikesh Mukherjee film starred Rajesh Khanna as a terminally ill man who affectionately nicknames Amitabh Bachchan\'s character \'Babu Moshai\'?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Anand (1971) remains one of Hindi cinema\'s best-loved films.', NULL, NULL),
(5221, 103, NULL, NULL, 3106, 'Amitabh Bachchan won the National Film Award for Best Supporting Actor for his role opposite Rajesh Khanna in which 1973 film?', '1', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Namak Haraam (1973) earned Bachchan this early recognition.', NULL, NULL),
(5222, 103, NULL, NULL, 3106, 'Which 1973 Hrishikesh Mukherjee film starred Amitabh Bachchan opposite his real-life wife Jaya Bhaduri, as a musician struggling with his wife\'s rising success?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Abhimaan (1973) released the same year the two married.', NULL, NULL),
(5223, 103, NULL, NULL, 3106, 'Which 1975 Hrishikesh Mukherjee comedy, starring Dharmendra, Amitabh Bachchan, Sharmila Tagore, and Jaya Bhaduri, remains a beloved classic of light-hearted mistaken-identity comedy?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Chupke Chupke (1975) is one of Hindi cinema\'s most cherished comedies.', NULL, NULL),
(5224, 103, NULL, NULL, 3106, 'Which 1976 Yash Chopra romantic drama, starring Amitabh Bachchan and Rakhee, features the celebrated title song \'Kabhi Kabhie Mere Dil Mein\'?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Kabhi Kabhie (1976) is remembered for its poetic soundtrack.', NULL, NULL),
(5225, 103, NULL, NULL, 3106, '\'Kabhi Kabhie Mere Dil Mein,\' the title song of Kabhi Kabhie (1976), was composed by:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Khayyam composed the acclaimed Kabhi Kabhie soundtrack.', NULL, NULL),
(5226, 103, NULL, NULL, 3106, 'The title song of Kabhi Kabhie was sung by Lata Mangeshkar and which male playback singer, voicing Amitabh Bachchan\'s character?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Mukesh sang the male portion of the title song.', NULL, NULL),
(5227, 103, NULL, NULL, 3106, 'Kishore Kumar became the dominant male playback voice of the early-to-mid 1970s, closely associated above all with which superstar actor of the period?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Kishore Kumar\'s voice became inseparable from Rajesh Khanna\'s screen image.', NULL, NULL),
(5228, 103, NULL, NULL, 3106, 'Which 1973 Nasir Hussain film, featuring the hit duet \'Chura Liya Hai Tumne,\' starred Zeenat Aman and Vijay Arora?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Yaadon Ki Baaraat (1973) was a major hit of the year.', NULL, NULL),
(5229, 103, NULL, NULL, 3106, '\'Chura Liya Hai Tumne Jo Dil Ko,\' from Yaadon Ki Baaraat (1973), was sung by Mohammed Rafi and which female singer?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Asha Bhosle sang this duet alongside Mohammed Rafi.', NULL, NULL),
(5230, 103, NULL, NULL, 3106, 'Yaadon Ki Baaraat (1973) was composed by which prolific music director, one of his major early hits?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'R.D. Burman composed the Yaadon Ki Baaraat soundtrack.', NULL, NULL),
(5231, 103, NULL, NULL, 3106, 'Mohammed Rafi won the National Film Award for Best Male Playback Singer for \'Kya Hua Tera Waada,\' from which 1977 film?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Hum Kisise Kum Naheen (1977) featured this award-winning song.', NULL, NULL),
(5232, 103, NULL, NULL, 3106, 'Which composer scored the soundtrack of Hum Kisise Kum Naheen (1977), including \'Kya Hua Tera Waada\'?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'R.D. Burman also composed this soundtrack.', NULL, NULL),
(5233, 103, NULL, NULL, 3106, 'Mohammed Rafi, one of Hindi cinema\'s most celebrated playback singers, passed away in which year, just as the decade of the 1970s gave way to the 1980s?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Mohammed Rafi passed away on 31 July 1980.', NULL, NULL),
(5234, 103, NULL, NULL, 3106, 'Which massively popular 1971 film, directed by Dev Anand and featuring the hit song \'Dum Maro Dum,\' gave Zeenat Aman her breakthrough role?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Hare Rama Hare Krishna (1971) launched Zeenat Aman to stardom.', NULL, NULL),
(5235, 103, NULL, NULL, 3106, '\'Dum Maro Dum\' from Hare Rama Hare Krishna (1971) was sung by:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Asha Bhosle sang the iconic \'Dum Maro Dum,\' winning a Filmfare Award for it.', NULL, NULL),
(5236, 103, NULL, NULL, 3106, 'Which 1971 film, starring Jeetendra and Asha Parekh, featured Asha Bhosle\'s iconic cabaret number \'Piya Tu Ab To Aaja,\' picturised on Helen?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Caravan (1971) featured this legendary cabaret number.', NULL, NULL),
(5237, 103, NULL, NULL, 3106, 'Asha Bhosle won consecutive Filmfare Awards for Best Female Playback Singer in the early 1970s for hit songs composed largely by which music director, whom she later married in 1980?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'R.D. Burman and Asha Bhosle married in 1980 after years of musical collaboration.', NULL, NULL),
(5238, 103, NULL, NULL, 3106, 'Which veteran playback singer, often called the \'Nightingale of India,\' continued to dominate female playback singing throughout the 1970s alongside her sister Asha Bhosle?', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Lata Mangeshkar remained the leading female playback voice through the decade.', NULL, NULL),
(5239, 103, NULL, NULL, 3106, 'Which 1970 Rajesh Khanna film, remembered for Kishore Kumar\'s evergreen song \'Yeh Shaam Mastani\' and co-starring Asha Parekh, was a major hit of the year?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Kati Patang (1970) featured this well-loved song.', NULL, NULL),
(5240, 103, NULL, NULL, 3106, 'Which 1972 Rajesh Khanna-Sharmila Tagore film, featuring Kishore Kumar\'s evergreen songs \'Chingari Koi Bhadke\' and \'Kuchh To Log Kahenge,\' was composed by R.D. Burman?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Amar Prem (1972) remains celebrated for its soundtrack.', NULL, NULL),
(5241, 103, NULL, NULL, 3106, 'Which 1979 Amitabh Bachchan film, in which he played a lovable con artist, featured the popular Kishore Kumar-Lata Mangeshkar duet \'Mere Paas Aao\'?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Mr. Natwarlal (1979) featured this popular duet.', NULL, NULL),
(5242, 103, NULL, NULL, 3106, 'Which 1979 Manmohan Desai film, starring Amitabh Bachchan, Shashi Kapoor, Rekha, and Parveen Babi as long-lost twins reunited as adults, became the highest-grossing Hindi film of that year?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Suhaag (1979) was the top-grossing Hindi film of 1979.', NULL, NULL),
(5243, 103, NULL, NULL, 3106, 'Which iconic real-life couple starred together on screen in several 1970s hits including Zanjeer, Abhimaan, and Chupke Chupke?', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Amitabh Bachchan and Jaya Bhaduri co-starred in several hits before and after their real-life marriage.', NULL, NULL),
(5244, 103, NULL, NULL, 3106, 'In which year did Amitabh Bachchan and Jaya Bhaduri marry, during the very period their on-screen partnership was flourishing?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The couple married in 1973, the same year Zanjeer and Abhimaan released.', NULL, NULL),
(5245, 103, NULL, NULL, 3106, 'Which composer duo, closely associated with several of Amitabh Bachchan\'s biggest 1970s hits including Zanjeer and Don, was one of Hindi cinema\'s most successful through the decade alongside R.D. Burman?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Kalyanji-Anandji scored the music for both Zanjeer and Don.', NULL, NULL),
(5246, 103, NULL, NULL, 3106, 'Which veteran character actor played Sher Khan, a reformed gambler who becomes a loyal ally to Amitabh Bachchan\'s police-inspector character in Zanjeer (1973)?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Pran played the memorable role of Sher Khan in Zanjeer.', NULL, NULL),
(5247, 103, NULL, NULL, 3106, 'Which actress, celebrated for her cabaret and dance numbers voiced by Asha Bhosle -- including \'Piya Tu Ab To Aaja\' in Caravan (1971) -- became one of the defining screen presences of 1970s Hindi cinema?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Helen was the era\'s most celebrated cabaret and dance performer.', NULL, NULL),
(5248, 103, NULL, NULL, 3106, 'Which 1975 Hrishikesh Mukherjee film starred Jaya Bhaduri as a terminally ill young woman, with Amitabh Bachchan playing her reclusive neighbour who falls in love with her?', '1', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Mili (1975) reunited Bachchan and Jaya Bhaduri with Hrishikesh Mukherjee.', NULL, NULL),
(5249, 103, NULL, NULL, 3106, 'Which lyricist penned \'Mehbooba Mehbooba\' for Sholay (1975), one of his many collaborations with composer R.D. Burman?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Anand Bakshi wrote the lyrics for \'Mehbooba Mehbooba.\'', NULL, NULL),
(5250, 103, NULL, NULL, 3106, 'Lata Mangeshkar, Asha Bhosle, Mohammed Rafi, and Kishore Kumar -- whose voices powered nearly every major Bollywood soundtrack of the period -- are together remembered as the defining playback singers of which decade?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'These four singers are collectively remembered as the defining voices of 1970s Hindi film music.', NULL, NULL),
(5301, 511, NULL, NULL, 3107, 'What is the most accurate definition of Artificial Intelligence (AI)?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'AI is broadly defined as the simulation of human intelligence processes - including learning, reasoning, and self-correction - by computer systems.', NULL, NULL),
(5302, 511, NULL, NULL, 3107, 'Which of the following best describes \"Narrow AI\" (also called Weak AI)?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Narrow AI is designed to perform a specific task well (e.g., recommendation engines, voice assistants) but cannot generalize beyond its trained domain.', NULL, NULL),
(5303, 511, NULL, NULL, 3107, 'What is the term for a hypothetical AI system with intelligence matching or exceeding human capability across all domains?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Artificial General Intelligence (AGI) refers to a system capable of understanding, learning, and applying knowledge across a wide range of tasks at a human level, unlike Narrow AI which is task-specific.', NULL, NULL),
(5304, 511, NULL, NULL, 3107, 'Which discipline is NOT typically considered a core subfield of AI?', '4', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Relational database normalization is a data-modeling technique in database design, not an AI subfield. ML, NLP, and Computer Vision are all core AI subfields.', NULL, NULL),
(5305, 511, NULL, NULL, 3107, 'What was the primary goal of the 1956 Dartmouth Workshop, widely considered the birthplace of AI as a field?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The 1956 Dartmouth Workshop, organized by John McCarthy and others, coined the term \"artificial intelligence\" and set out to explore machine simulation of intelligence.', NULL, NULL),
(5306, 511, NULL, NULL, 3107, 'Which of these is an example of an AI \"agent\" acting in an environment?', '3', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'An AI agent perceives its environment through sensors and acts upon it through actuators to achieve goals - a self-driving car is a classic example.', NULL, NULL),
(5307, 511, NULL, NULL, 3107, 'What is \"knowledge mining\" in the context of AI workloads?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Knowledge mining uses AI to extract structured, searchable information from large volumes of unstructured or semi-structured content such as documents and scanned files.', NULL, NULL),
(5308, 511, NULL, NULL, 3107, 'Which best describes the relationship between AI, Machine Learning, and Deep Learning?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'AI is the broadest field; Machine Learning is a subset of AI focused on learning from data; Deep Learning is a subset of ML that uses multi-layered neural networks.', NULL, NULL),
(5309, 511, NULL, NULL, 3107, 'What is an \"expert system\" in classical AI?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Expert systems use encoded domain knowledge and inference rules (if-then logic) to mimic the decision-making of a human expert, predating modern statistical machine learning.', NULL, NULL),
(5310, 511, NULL, NULL, 3107, 'Which of the following is generally considered a Turing Test-style evaluation of AI?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The Turing Test evaluates a machines ability to exhibit intelligent behavior indistinguishable from a human, typically through natural-language conversation.', NULL, NULL),
(5311, 511, NULL, NULL, 3107, 'In supervised learning, what does the training data consist of?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Supervised learning trains a model on labeled examples - inputs paired with the correct outputs - so it can learn to map new inputs to outputs.', NULL, NULL),
(5312, 511, NULL, NULL, 3107, 'Which type of machine learning is used when you want to group similar, unlabeled data points together without predefined categories?', '3', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Clustering is an unsupervised learning technique that groups data points based on similarity without relying on labeled outcomes.', NULL, NULL),
(5313, 511, NULL, NULL, 3107, 'What type of machine learning problem is \"predicting a houses sale price from its features\"?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Regression predicts a continuous numeric value (like price), as opposed to classification which predicts discrete categories.', NULL, NULL),
(5314, 511, NULL, NULL, 3107, 'Which of the following are examples of classification problems? Select all that apply.', '1,3,4', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MULTI', 3, 'Classification predicts a discrete label/category. Spam detection, tumor diagnosis, and product-category identification are all classification tasks; predicting an exact temperature is regression.', NULL, NULL),
(5315, 511, NULL, NULL, 3107, 'In reinforcement learning, what is the primary mechanism by which an agent learns?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Reinforcement learning agents learn a policy by taking actions in an environment and receiving feedback in the form of rewards or penalties, aiming to maximize cumulative reward.', NULL, NULL),
(5316, 511, NULL, NULL, 3107, 'What is \"overfitting\" in machine learning?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Overfitting occurs when a model learns the training data too closely, including its noise, and fails to generalize to new data.', NULL, NULL),
(5317, 511, NULL, NULL, 3107, 'Which technique is commonly used to reduce overfitting in a machine learning model?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Regularization techniques (L1/L2, dropout, early stopping) constrain model complexity or add noise during training to improve generalization and reduce overfitting.', NULL, NULL),
(5318, 511, NULL, NULL, 3107, 'What is the purpose of splitting a dataset into training, validation, and test sets?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Splitting data allows model training, hyperparameter tuning (validation), and a final unbiased evaluation (test set) that was not used in either training or tuning.', NULL, NULL),
(5319, 511, NULL, NULL, 3107, 'What does \"feature engineering\" refer to in a machine learning pipeline?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Feature engineering involves selecting, transforming, or constructing input variables (features) so a model can learn patterns more effectively.', NULL, NULL),
(5320, 511, NULL, NULL, 3107, 'Which of the following is an example of \"semi-supervised learning\"?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Semi-supervised learning combines a small labeled dataset with a larger unlabeled dataset to improve learning efficiency when labels are expensive to obtain.', NULL, NULL),
(5321, 511, NULL, NULL, 3107, 'What is a \"hyperparameter\" in machine learning?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Hyperparameters (e.g., learning rate, batch size, number of layers) are set before training and control how the learning process behaves, unlike model parameters which are learned.', NULL, NULL),
(5322, 511, NULL, NULL, 3107, 'Which metric is most appropriate for evaluating a classification model on an imbalanced dataset (e.g., 95% negative, 5% positive)?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'On imbalanced datasets, accuracy can be misleading (a model predicting all-negative could score 95%). Precision, recall, and F1-score better capture performance on the minority class.', NULL, NULL),
(5323, 511, NULL, NULL, 3107, 'What does \"cross-validation\" help estimate in a machine learning workflow?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Cross-validation (e.g., k-fold) repeatedly trains and evaluates a model on different data splits to give a more reliable estimate of generalization performance.', NULL, NULL),
(5324, 511, NULL, NULL, 3107, 'In the context of decision trees, what does \"pruning\" accomplish?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Pruning removes branches that add complexity without meaningfully improving predictions on unseen data, helping prevent overfitting.', NULL, NULL),
(5325, 511, NULL, NULL, 3107, 'What is \"transfer learning\"?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Transfer learning takes knowledge (weights/features) learned from one task or dataset and applies it to a new, related task, often reducing the data and time needed to train.', NULL, NULL),
(5326, 511, NULL, NULL, 3107, 'What is the basic computational unit of an artificial neural network inspired by biological neurons?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The perceptron, or artificial neuron, is the basic building block of a neural network - it takes weighted inputs, applies a bias, and passes the result through an activation function.', NULL, NULL),
(5327, 511, NULL, NULL, 3107, 'What is the role of an \"activation function\" in a neural network?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Activation functions (e.g., ReLU, sigmoid, tanh) introduce non-linearity, allowing neural networks to model complex, non-linear relationships in data.', NULL, NULL),
(5328, 511, NULL, NULL, 3107, 'What does \"backpropagation\" do in neural network training?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Backpropagation calculates the gradient of the loss function with respect to each weight by propagating error backward, enabling weight updates via gradient descent.', NULL, NULL),
(5329, 511, NULL, NULL, 3107, 'Which type of neural network architecture is most commonly used for image recognition tasks?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Convolutional Neural Networks (CNNs) use convolutional layers to detect spatial patterns like edges and shapes, making them well-suited for image recognition.', NULL, NULL),
(5330, 511, NULL, NULL, 3107, 'Which neural network architecture is traditionally best suited for sequential data such as time series or text, due to its internal memory of previous inputs?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Recurrent Neural Networks (RNNs), including LSTM and GRU variants, maintain an internal state that captures information from previous time steps, suiting them to sequential data.', NULL, NULL),
(5331, 511, NULL, NULL, 3107, 'What is the \"vanishing gradient\" problem in deep neural networks?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'In deep networks, gradients can shrink exponentially as they are backpropagated through many layers, making it difficult for earlier layers to learn effectively.', NULL, NULL),
(5332, 511, NULL, NULL, 3107, 'What is the primary innovation of the Transformer architecture that enabled modern large language models?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Transformers use self-attention to weigh relationships between all tokens in a sequence in parallel, overcoming the sequential bottleneck of RNNs and enabling large-scale language models.', NULL, NULL),
(5333, 511, NULL, NULL, 3107, 'What is \"dropout\" used for in training deep neural networks?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Dropout randomly deactivates a subset of neurons during each training iteration, which prevents co-adaptation and helps the network generalize better.', NULL, NULL),
(5334, 511, NULL, NULL, 3107, 'What does \"epoch\" mean in the context of training a neural network?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'An epoch is one complete pass of the entire training dataset through the learning algorithm; training typically involves many epochs.', NULL, NULL),
(5335, 511, NULL, NULL, 3107, 'Which optimization algorithm is most commonly used as the default for training deep learning models today?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Adam (Adaptive Moment Estimation) combines momentum and adaptive learning rates and is one of the most widely used optimizers for training deep neural networks.', NULL, NULL),
(5336, 511, NULL, NULL, 3107, 'What is \"batch size\" in neural network training?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Batch size refers to how many training samples are processed together before the model updates its weights during one training step.', NULL, NULL),
(5337, 511, NULL, NULL, 3107, 'What does GAN stand for, and what is its core idea?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A Generative Adversarial Network (GAN) pits a generator (creates fake data) against a discriminator (distinguishes real from fake) in an adversarial training process to produce realistic synthetic data.', NULL, NULL),
(5338, 511, NULL, NULL, 3107, 'What is \"tokenization\" in Natural Language Processing?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Tokenization splits raw text into smaller units (tokens) - words, subwords, or characters - which are then converted into numerical representations for model processing.', NULL, NULL),
(5339, 511, NULL, NULL, 3107, 'What are \"word embeddings\"?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Word embeddings represent words as dense vectors in a continuous space such that semantically similar words are located close to one another.', NULL, NULL),
(5340, 511, NULL, NULL, 3107, 'Which NLP task involves determining whether a piece of text expresses a positive, negative, or neutral opinion?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Sentiment analysis classifies text based on the emotional tone or opinion it expresses, typically as positive, negative, or neutral.', NULL, NULL),
(5341, 511, NULL, NULL, 3107, 'What does \"Named Entity Recognition\" (NER) identify in text?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'NER locates and classifies named entities in text into predefined categories such as person names, organizations, locations, and dates.', NULL, NULL),
(5342, 511, NULL, NULL, 3107, 'What is the purpose of a language models \"context window\"?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The context window defines how many tokens of prior text a language model can attend to when generating a response; text beyond this window is not considered.', NULL, NULL),
(5343, 511, NULL, NULL, 3107, 'Which of these best describes \"machine translation\" as an NLP task?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Machine translation automatically translates text or speech from a source language into a target language while attempting to preserve meaning.', NULL, NULL),
(5344, 511, NULL, NULL, 3107, 'What is \"text summarization\" in NLP typically used for?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Text summarization condenses a longer piece of text into a shorter version that retains the most important information and meaning.', NULL, NULL),
(5345, 511, NULL, NULL, 3107, 'What is a key difference between \"extractive\" and \"abstractive\" text summarization?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Extractive summarization pulls exact sentences or phrases from the source text, while abstractive summarization generates new phrasing that may not appear verbatim in the original.', NULL, NULL),
(5346, 511, NULL, NULL, 3107, 'Which underlying technique allows modern chatbots to maintain context across a multi-turn conversation?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Conversational AI systems typically include prior turns of the dialogue (or a summarized version) in the models input context so responses stay relevant to the ongoing conversation.', NULL, NULL),
(5347, 511, NULL, NULL, 3107, 'What does \"speech-to-text\" (STT) technology do?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Speech-to-text (also called automatic speech recognition) converts spoken language captured as audio into written text.', NULL, NULL),
(5348, 511, NULL, NULL, 3107, 'What does \"image classification\" accomplish in computer vision?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Image classification assigns a label (or labels) to an entire image describing its content, such as \"cat\" or \"landscape\".', NULL, NULL),
(5349, 511, NULL, NULL, 3107, 'How does \"object detection\" differ from basic image classification?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Object detection combines classification and localization - it identifies multiple objects in an image and marks their positions, typically with bounding boxes.', NULL, NULL),
(5350, 511, NULL, NULL, 3107, 'What does OCR (Optical Character Recognition) do?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'OCR extracts text embedded in images or scanned documents and converts it into editable, searchable digital text.', NULL, NULL),
(5351, 511, NULL, NULL, 3107, 'What is \"semantic segmentation\" in computer vision?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Semantic segmentation assigns a class label to every pixel in an image, producing a dense map that outlines the exact shape and extent of each object category.', NULL, NULL),
(5352, 511, NULL, NULL, 3107, 'Which computer vision technique would be most appropriate for verifying a persons identity using their facial features?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Face recognition/verification analyzes facial features to identify or confirm the identity of a person, commonly used for authentication.', NULL, NULL),
(5353, 511, NULL, NULL, 3107, 'What does \"image captioning\" combine to generate a natural-language description of an image?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Image captioning models combine computer vision (to extract visual features and understand content) with natural language generation (to produce a coherent textual description).', NULL, NULL),
(5354, 511, NULL, NULL, 3107, 'What kind of AI workload is used to detect unusual patterns, such as fraudulent transactions or defective products on an assembly line?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Anomaly detection identifies data points, events, or observations that deviate significantly from the norm, commonly applied to fraud detection and quality control.', NULL, NULL),
(5355, 511, NULL, NULL, 3107, 'In computer vision, what is the purpose of \"data augmentation\" (e.g., rotating, flipping, or cropping training images)?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Data augmentation creates modified versions of training images (rotation, flipping, cropping, etc.) to increase dataset diversity and reduce overfitting.', NULL, NULL),
(5356, 511, NULL, NULL, 3107, 'What is a Large Language Model (LLM)?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'LLMs are deep neural networks, typically based on the Transformer architecture, trained on massive text corpora to understand and generate natural language.', NULL, NULL),
(5357, 511, NULL, NULL, 3107, 'What is \"prompt engineering\"?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Prompt engineering involves crafting effective inputs (instructions, context, examples) to guide a generative AI model toward producing the desired output.', NULL, NULL),
(5358, 511, NULL, NULL, 3107, 'What does \"fine-tuning\" a pretrained language model involve?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Fine-tuning takes a model that was pretrained on general data and continues training it on a narrower, task-specific dataset to improve performance on that task.', NULL, NULL),
(5359, 511, NULL, NULL, 3107, 'What is \"few-shot learning\" (or few-shot prompting) in the context of LLMs?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Few-shot prompting includes a small number of example input-output pairs directly in the prompt, helping the model infer the desired task pattern without any weight updates.', NULL, NULL),
(5360, 511, NULL, NULL, 3107, 'Which of the following are common risks associated with generative AI outputs? Select all that apply.', '1,3,4', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MULTI', 3, 'Generative AI can hallucinate false information, reflect biases from training data, and produce harmful content without safeguards. It is not inherently deterministic or guaranteed to be accurate.', NULL, NULL),
(5361, 511, NULL, NULL, 3107, 'What does \"grounding\" mean when applied to a generative AI application?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Grounding supplies a generative model with relevant external or current information (often via retrieval-augmented generation) so its responses are more accurate and less likely to be fabricated.', NULL, NULL),
(5362, 511, NULL, NULL, 3107, 'What is Retrieval-Augmented Generation (RAG)?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'RAG combines an information retrieval step (fetching relevant documents from a knowledge base) with a generative model, which then uses that retrieved context to produce a grounded, more accurate response.', NULL, NULL),
(5363, 511, NULL, NULL, 3107, 'What is a key capability of multimodal generative AI models?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Multimodal models are designed to process and/or generate multiple types of data (text, images, audio, video) within a unified architecture.', NULL, NULL),
(5364, 511, NULL, NULL, 3107, 'What is the primary function of a model like DALL-E or Stable Diffusion?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'DALL-E and Stable Diffusion are generative models that create images from text prompts describing the desired visual content.', NULL, NULL),
(5365, 511, NULL, NULL, 3107, 'What does \"temperature\" control when generating text from a language model?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Temperature is a sampling parameter that controls randomness in generated text: lower temperatures make outputs more focused and deterministic, higher temperatures increase diversity and creativity.', NULL, NULL),
(5366, 511, NULL, NULL, 3107, 'What is a \"system message\" (or system prompt) used for in a conversational generative AI application?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A system message sets high-level instructions, persona, tone, and boundaries that guide how the AI assistant should behave throughout the conversation.', NULL, NULL),
(5367, 511, NULL, NULL, 3107, 'What is \"content filtering\" in a generative AI service typically designed to do?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Content filtering systems scan prompts and generated outputs for harmful, offensive, or policy-violating content and block or flag it accordingly.', NULL, NULL),
(5368, 511, NULL, NULL, 3107, 'What is \"in-context learning\" in large language models?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'In-context learning describes an LLMs ability to infer how to perform a task from examples or instructions in the prompt itself, without any gradient updates to the models parameters.', NULL, NULL),
(5369, 511, NULL, NULL, 3107, 'Why might a generative AI model \"hallucinate\" incorrect facts?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'LLMs generate text by predicting statistically likely sequences of tokens; this can produce fluent, plausible-sounding statements that are not actually grounded in fact, known as hallucination.', NULL, NULL),
(5370, 511, NULL, NULL, 3107, 'Which approach helps reduce hallucinations by giving a generative model access to authoritative, current data sources instead of relying solely on its training data?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Grounding a model with retrieval-augmented generation gives it access to verified, current external data at query time, reducing reliance on potentially outdated or incomplete training knowledge.', NULL, NULL),
(5371, 511, NULL, NULL, 3107, 'What is \"algorithmic bias\" in AI systems?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Algorithmic bias occurs when a model produces systematically unfair or skewed outcomes for certain groups, frequently because the training data reflects existing societal or sampling biases.', NULL, NULL),
(5372, 511, NULL, NULL, 3107, 'Which of the following are commonly cited pillars/principles of Responsible AI? Select all that apply.', '1,3,4', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MULTI', 3, 'Responsible AI frameworks commonly emphasize fairness, transparency/explainability, privacy and security, accountability, reliability, and inclusiveness - not simply maximizing model size.', NULL, NULL),
(5373, 511, NULL, NULL, 3107, 'What does \"explainability\" mean in the context of AI systems?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Explainability refers to how well humans can understand and interpret why an AI model produced a particular output or decision.', NULL, NULL),
(5374, 511, NULL, NULL, 3107, 'Why is data privacy an important consideration when building AI systems?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'AI systems frequently process personal or sensitive data; protecting that data is essential to prevent harm, comply with regulations, and maintain user trust.', NULL, NULL),
(5375, 511, NULL, NULL, 3107, 'What does the Responsible AI principle of \"inclusiveness\" aim to achieve?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Inclusiveness in Responsible AI means designing systems that consider and serve diverse populations, including people with different abilities, backgrounds, and needs, rather than excluding groups.', NULL, NULL),
(5376, 511, NULL, NULL, 3107, 'What is a \"human-in-the-loop\" approach in AI system design?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Human-in-the-loop design keeps people involved in reviewing, approving, or overriding AI decisions, particularly important for high-stakes or sensitive use cases.', NULL, NULL),
(5377, 511, NULL, NULL, 3107, 'Why should AI systems be designed with \"reliability and safety\" as a core principle?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Reliability and safety ensure AI systems behave predictably and safely, including graceful handling of unusual or edge-case inputs, to minimize the risk of harm.', NULL, NULL),
(5378, 511, NULL, NULL, 3107, 'What is a potential consequence of training a facial recognition model primarily on data from one demographic group?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Training data that lacks diversity can cause a model to perform worse for underrepresented groups, a well-documented issue in facial recognition systems.', NULL, NULL),
(5379, 511, NULL, NULL, 3107, 'What role does \"accountability\" play as a Responsible AI principle?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Accountability means the people and organizations building and deploying AI systems remain responsible for their behavior and consequences, including governance and oversight.', NULL, NULL),
(5380, 511, NULL, NULL, 3107, 'Which practice helps improve transparency when deploying an AI-powered product to end users?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Transparency practices include clearly informing users when they are interacting with AI and communicating the systems capabilities, limitations, and appropriate use.', NULL, NULL),
(5381, 511, NULL, NULL, 3107, 'Why is high-quality, representative training data critical to building an effective AI model?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The principle \"garbage in, garbage out\" applies strongly to AI: model quality depends heavily on the quality, relevance, and representativeness of its training data.', NULL, NULL),
(5382, 511, NULL, NULL, 3107, 'What is a \"confusion matrix\" used for in evaluating a classification model?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A confusion matrix tabulates a classification models predictions against actual labels, showing true/false positives and negatives, which underlies metrics like precision and recall.', NULL, NULL),
(5383, 511, NULL, NULL, 3107, 'What does \"precision\" measure in a classification models evaluation?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Precision = True Positives / (True Positives + False Positives) - it measures how many of the predicted-positive cases were actually positive.', NULL, NULL),
(5384, 511, NULL, NULL, 3107, 'What does \"recall\" (sensitivity) measure in a classification models evaluation?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Recall = True Positives / (True Positives + False Negatives) - it measures how many of the actual positive cases the model successfully identified.', NULL, NULL),
(5385, 511, NULL, NULL, 3107, 'What is the purpose of a labeled datasets \"ground truth\"?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Ground truth refers to the accurate, verified labels used as the reference standard for training and evaluating a models predictions.', NULL, NULL),
(5386, 511, NULL, NULL, 3107, 'What does \"MLOps\" primarily refer to?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'MLOps (Machine Learning Operations) applies DevOps-like practices - automation, monitoring, versioning, and CI/CD - to the lifecycle of deploying and maintaining ML models in production.', NULL, NULL),
(5387, 511, NULL, NULL, 3107, 'Why might an organization use cloud-based AI services rather than building and training models entirely from scratch?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Cloud AI platforms offer prebuilt models, scalable compute, and managed infrastructure, allowing organizations to adopt AI capabilities faster and with less specialized expertise than building everything from scratch.', NULL, NULL),
(5388, 511, NULL, NULL, 3107, 'What is \"model drift\" (or concept drift) in a deployed machine learning system?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Model drift occurs when the statistical properties of real-world input data (or the relationship being predicted) change over time, causing a previously accurate models performance to degrade.', NULL, NULL),
(5389, 511, NULL, NULL, 3107, 'What is the main benefit of using a version-controlled model registry in an MLOps workflow?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A model registry tracks versions of trained models along with metadata (metrics, lineage, parameters), supporting reproducibility, auditing, and safe rollback to previous versions.', NULL, NULL),
(5390, 511, NULL, NULL, 3107, 'What does \"latency\" measure when evaluating an AI model in production?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Latency measures how long it takes a deployed model to return a prediction after receiving an input, which is critical for real-time applications.', NULL, NULL),
(5391, 511, NULL, NULL, 3107, 'Which AI capability powers a virtual assistants ability to understand spoken commands like \"set a timer for 10 minutes\"?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Virtual assistants convert spoken audio to text (speech recognition) and then interpret the intent of that text (natural language understanding) to act on commands.', NULL, NULL),
(5392, 511, NULL, NULL, 3107, 'Which AI-powered technique do streaming services like video or music platforms commonly use to suggest content to users?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Recommendation systems analyze user behavior and preferences (collaborative filtering) or item attributes (content-based filtering) to suggest relevant content.', NULL, NULL),
(5393, 511, NULL, NULL, 3107, 'How can AI be applied in healthcare to assist radiologists?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'AI models can analyze medical images to flag potential anomalies (like tumors), assisting radiologists in prioritizing and reviewing cases faster, with the human expert making the final call.', NULL, NULL),
(5394, 511, NULL, NULL, 3107, 'What is a common application of AI-based anomaly detection in the finance industry?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Fraud detection systems use anomaly detection to flag transactions that deviate significantly from a customers typical spending patterns.', NULL, NULL),
(5395, 511, NULL, NULL, 3107, 'Which of the following best describes a chatbot built using conversational AI?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Conversational AI chatbots use NLP techniques to interpret user messages and generate contextually relevant responses in a dialogue format.', NULL, NULL),
(5396, 511, NULL, NULL, 3107, 'In manufacturing, how is computer vision commonly applied on a production line?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Computer vision systems can inspect products in real time, detecting visual defects like scratches, misalignments, or missing components on a production line.', NULL, NULL),
(5397, 511, NULL, NULL, 3107, 'What is a common use case for AI-driven forecasting in retail?', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Demand forecasting models predict future sales or demand trends, helping retailers optimize inventory levels, reduce stockouts, and minimize excess stock.', NULL, NULL),
(5398, 511, NULL, NULL, 3107, 'Which AI capability would be most useful for automatically redacting sensitive personal information from scanned documents?', '1', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Automated redaction typically uses OCR to extract text and named entity recognition (often paired with layout/image understanding) to identify and mask sensitive entities like names, ID numbers, or addresses.', NULL, NULL),
(5399, 511, NULL, NULL, 3107, 'What AI capability underlies tools that automatically generate code suggestions or complete code snippets for developers?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'AI coding assistants use large language models trained on vast amounts of source code, predicting likely next tokens to generate contextually relevant code suggestions and completions.', NULL, NULL),
(5400, 511, NULL, NULL, 3107, 'Which of the following is a good example of AI applied to accessibility technology?', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'AI-generated real-time captioning uses speech recognition to transcribe live audio, improving accessibility for people who are deaf or hard of hearing.', NULL, NULL),
(5401, 22, NULL, NULL, 3109, 'Which of the following is a contact force?', '3', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Friction requires two surfaces to be in physical contact, unlike gravitational, magnetic, and electrostatic forces which act at a distance.', NULL, NULL),
(5402, 22, NULL, NULL, 3109, 'Thrust per unit area is called:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Pressure is defined as the force (thrust) acting perpendicularly per unit area of a surface.', NULL, NULL);
INSERT INTO `questions` (`QuestionId`, `SubjectInfoId`, `ChapterInfoId`, `CaseStudyId`, `ExamInfoId`, `QuestionDesc`, `CorrectAnswer`, `ImageInd`, `NumofImages`, `ImageLoc`, `OperatorInd`, `Complexity`, `IsActive`, `IsDeleted`, `DeletedAt`, `DeletedBy`, `QuestionType`, `ExpectedAnswerCount`, `Explanation`, `LinkedFromQuestionId`, `TranslatedFromQuestionId`) VALUES
(5403, 22, NULL, NULL, 3109, 'Which force opposes relative motion between two surfaces in contact?', '3', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Friction is the force that opposes the relative sliding motion between two surfaces in contact.', NULL, NULL),
(5404, 22, NULL, NULL, 3109, 'Sound is produced due to:', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Sound originates from the vibration of an object, which creates pressure waves that travel through a medium.', NULL, NULL),
(5405, 22, NULL, NULL, 3109, 'The SI unit of frequency is:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Frequency, the number of oscillations per second, is measured in hertz (Hz).', NULL, NULL),
(5406, 22, NULL, NULL, 3109, 'Lightning during a thunderstorm is caused due to:', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Lightning is an electric spark caused by the discharge of static electricity built up in clouds due to friction between air and water particles.', NULL, NULL),
(5407, 22, NULL, NULL, 3109, 'Which of the following methods reduces friction between two surfaces?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Lubricants like oil form a thin layer between surfaces, reducing direct contact and hence reducing friction.', NULL, NULL),
(5408, 22, NULL, NULL, 3109, 'The image formed by a plane mirror is:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A plane mirror always forms a virtual, erect image that is laterally inverted but the same size as the object.', NULL, NULL),
(5409, 22, NULL, NULL, 3109, 'The SI unit of force is:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Force is measured in newtons (N) in the SI system, named after Sir Isaac Newton.', NULL, NULL),
(5410, 22, NULL, NULL, 3109, 'According to Newtons First Law of Motion, an object remains at rest or in uniform motion in a straight line unless acted upon by:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Newtons First Law (the law of inertia) states that an object continues in its state of rest or uniform motion unless an unbalanced external force acts on it.', NULL, NULL),
(5411, 22, NULL, NULL, 3109, 'The SI unit of work is:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Work done is measured in joules (J), where 1 joule = 1 newton x 1 metre.', NULL, NULL),
(5412, 22, NULL, NULL, 3109, 'Which of the following remains constant for a freely falling body near Earths surface, ignoring air resistance?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Near Earths surface, the acceleration due to gravity (g approx 9.8 m/s^2) stays constant during free fall, while velocity, momentum, and kinetic energy all increase.', NULL, NULL),
(5413, 22, NULL, NULL, 3109, 'The universal law of gravitation states that the gravitational force between two objects is directly proportional to the product of their masses and inversely proportional to:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Newtons law of gravitation: F = G(m1*m2)/r^2, so the force is inversely proportional to the square of the distance between the two objects.', NULL, NULL),
(5414, 22, NULL, NULL, 3109, 'Which of the following is a vector quantity?', '4', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Displacement has both magnitude and direction, making it a vector quantity, unlike speed, distance, and mass, which are scalars.', NULL, NULL),
(5415, 22, NULL, NULL, 3109, 'Which type of wave requires a material medium to travel and cannot pass through a vacuum?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Sound is a mechanical wave that needs a medium (solid, liquid, or gas) to propagate; it cannot travel through a vacuum, unlike electromagnetic waves.', NULL, NULL),
(5416, 22, NULL, NULL, 3109, 'The minimum time interval for which the human ear can distinguish two separate sounds is about:', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Due to the persistence of hearing, the human ear can distinguish two sounds as separate only if they are at least about 0.1 second apart.', NULL, NULL),
(5417, 22, NULL, NULL, 3109, 'The loudness of a sound mainly depends on its:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Loudness is determined primarily by the amplitude of the sound wave; a larger amplitude produces a louder sound.', NULL, NULL),
(5418, 22, NULL, NULL, 3109, 'The power of a lens is measured in:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The power of a lens, defined as the reciprocal of its focal length in metres, is measured in dioptres (D).', NULL, NULL),
(5419, 22, NULL, NULL, 3109, 'Which type of mirror is commonly used as a rear-view mirror in vehicles because it gives a wider field of view?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A convex mirror always forms a diminished, virtual image and provides a wider field of view, making it ideal for vehicle rear-view mirrors.', NULL, NULL),
(5420, 22, NULL, NULL, 3109, 'One kilowatt-hour (kWh), the commercial unit of electrical energy, is equal to:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, '1 kWh = 1000 watts used for 3600 seconds (1 hour) = 3.6 x 10^6 joules.', NULL, NULL),
(5421, 22, NULL, NULL, 3109, 'Ohms law states that, at constant temperature, the current through a conductor is directly proportional to:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Ohms law: V = IR, meaning current (I) is directly proportional to the potential difference (V) applied across the conductor at constant temperature.', NULL, NULL),
(5422, 22, NULL, NULL, 3109, 'Which effect of electric current produces a magnetic field around a current-carrying conductor?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Oersted discovered that a current-carrying conductor produces a magnetic field around it, known as the magnetic effect of electric current.', NULL, NULL),
(5423, 22, NULL, NULL, 3109, 'The device that converts mechanical energy into electrical energy by rotating a coil in a magnetic field is called a:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'An electric generator works on the principle of electromagnetic induction, converting mechanical energy into electrical energy by rotating a coil within a magnetic field.', NULL, NULL),
(5424, 22, NULL, NULL, 3109, 'Which of the following is a renewable source of energy?', '3', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Solar energy is continuously replenished by the sun and does not get depleted with use, unlike fossil fuels such as coal, petroleum, and natural gas.', NULL, NULL),
(5425, 22, NULL, NULL, 3109, 'The bending of light as it passes obliquely from one transparent medium to another is called:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Refraction is the change in direction (bending) of light as it travels from one medium to another due to a change in its speed.', NULL, NULL),
(5426, 23, NULL, NULL, 3109, 'Which of the following is a synthetic fibre?', '4', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Nylon is a man-made (synthetic) fibre produced from chemical raw materials, unlike cotton, wool, and silk, which are natural fibres.', NULL, NULL),
(5427, 23, NULL, NULL, 3109, 'Which gas present in air is essential for combustion?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Combustion is a chemical process that requires oxygen to sustain burning; without oxygen, a fire cannot continue.', NULL, NULL),
(5428, 23, NULL, NULL, 3109, 'A substance which does not catch fire easily is called:', '3', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Non-combustible substances resist catching fire and burning, unlike combustible or inflammable materials.', NULL, NULL),
(5429, 23, NULL, NULL, 3109, 'Coal and petroleum are examples of:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Coal and petroleum formed from the remains of dead plants and animals buried under the earth over millions of years, making them fossil fuels.', NULL, NULL),
(5430, 23, NULL, NULL, 3109, 'Which metal is commonly used to galvanize iron sheets to prevent rusting?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Galvanization involves coating iron or steel with a layer of zinc, which protects the metal underneath from rusting.', NULL, NULL),
(5431, 23, NULL, NULL, 3109, 'The smallest particle of an element that can take part in a chemical reaction is called a(n):', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'An atom is the smallest unit of an element that retains the chemical properties of that element and can participate in chemical reactions.', NULL, NULL),
(5432, 23, NULL, NULL, 3109, 'The three states of matter can be interconverted mainly by changing:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Matter changes between solid, liquid, and gaseous states primarily due to changes in temperature and pressure.', NULL, NULL),
(5433, 23, NULL, NULL, 3109, 'Which of the following is a pure substance?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Distilled water contains only H2O molecules with no dissolved impurities, making it a pure substance, unlike milk, air, and soil, which are mixtures.', NULL, NULL),
(5434, 23, NULL, NULL, 3109, 'The process of separating a dissolved solid from a liquid by heating the liquid to vapour and then condensing it is called:', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Distillation involves heating a liquid to form vapour and then condensing the vapour back into liquid, leaving the dissolved solid behind.', NULL, NULL),
(5435, 23, NULL, NULL, 3109, 'Who is credited with the discovery of the electron?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'J.J. Thomson discovered the electron in 1897 through his experiments with cathode rays.', NULL, NULL),
(5436, 23, NULL, NULL, 3109, 'The nucleus of an atom contains:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The atomic nucleus is composed of positively charged protons and neutral neutrons, while electrons revolve around it.', NULL, NULL),
(5437, 23, NULL, NULL, 3109, 'The number of protons present in the nucleus of an atom is called its:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The atomic number of an element equals the number of protons in the nucleus of its atoms and determines the elements identity.', NULL, NULL),
(5438, 23, NULL, NULL, 3109, 'Isotopes of an element have the same number of protons but a different number of:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Isotopes are atoms of the same element with identical proton counts but differing numbers of neutrons, giving them different mass numbers.', NULL, NULL),
(5439, 23, NULL, NULL, 3109, 'Which of the following is NOT a physical change?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Burning of paper is a chemical change because it produces new substances (ash, gases) and cannot be easily reversed, unlike the other reversible physical changes listed.', NULL, NULL),
(5440, 23, NULL, NULL, 3109, 'A chemical reaction in which a single compound breaks down into two or more simpler substances is called a:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'In a decomposition reaction, one reactant breaks down into two or more simpler products, often with the input of heat, light, or electricity.', NULL, NULL),
(5441, 23, NULL, NULL, 3109, 'When calcium oxide reacts with water to form calcium hydroxide and releases a large amount of heat, this is an example of a(n):', '1', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Two substances (calcium oxide and water) combine to form one product (calcium hydroxide) while releasing heat, making it an exothermic combination reaction.', NULL, NULL),
(5442, 23, NULL, NULL, 3109, 'A reaction in which oxygen is added to a substance, or hydrogen is removed from it, is called:', '1', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Oxidation is defined as the gain of oxygen or the loss of hydrogen by a substance during a chemical reaction.', NULL, NULL),
(5443, 23, NULL, NULL, 3109, 'The pH value of a neutral solution at room temperature is:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A pH of 7 indicates a neutral solution; values below 7 are acidic and values above 7 are basic (alkaline).', NULL, NULL),
(5444, 23, NULL, NULL, 3109, 'Which indicator turns pink in a basic solution and remains colourless in an acidic solution?', '3', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Phenolphthalein is colourless in acidic and neutral solutions but turns pink/magenta in basic solutions.', NULL, NULL),
(5445, 23, NULL, NULL, 3109, 'Common salt (sodium chloride) is formed by the reaction of hydrochloric acid with which base?', '1', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Hydrochloric acid reacts with sodium hydroxide in a neutralization reaction to form sodium chloride (common salt) and water.', NULL, NULL),
(5446, 23, NULL, NULL, 3109, 'When metals react with dilute acids, they typically produce a salt and which gas?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Reactive metals react with dilute acids to displace hydrogen gas, forming the corresponding metal salt.', NULL, NULL),
(5447, 23, NULL, NULL, 3109, 'Which of the following metals reacts vigorously with cold water to readily release hydrogen gas?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Sodium is a highly reactive metal that reacts vigorously with cold water, releasing hydrogen gas and forming sodium hydroxide.', NULL, NULL),
(5448, 23, NULL, NULL, 3109, 'Elements in the Modern Periodic Table are arranged in order of increasing:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The Modern Periodic Law states that properties of elements are a periodic function of their atomic number, which is the basis for their arrangement.', NULL, NULL),
(5449, 23, NULL, NULL, 3109, 'The general formula for saturated hydrocarbons (alkanes) is:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Alkanes are saturated hydrocarbons containing only single bonds, following the general formula CnH2n+2.', NULL, NULL),
(5450, 23, NULL, NULL, 3109, 'The property of carbon atoms to bond with other carbon atoms, forming long chains, branched chains, or rings, is called:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Catenation is the unique ability of carbon atoms to form strong covalent bonds with each other, creating chains, branches, and rings.', NULL, NULL),
(5451, 3, NULL, NULL, 3109, 'The additive inverse of -7/9 is:', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The additive inverse of a number is the value that, when added to it, gives zero; -7/9 + 7/9 = 0.', NULL, NULL),
(5452, 3, NULL, NULL, 3109, 'Solve for x: 2x + 5 = 15.', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Subtracting 5 from both sides gives 2x = 10, and dividing by 2 gives x = 5.', NULL, NULL),
(5453, 3, NULL, NULL, 3109, 'The sum of the interior angles of a quadrilateral is:', '3', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A quadrilateral can be divided into two triangles, and since each triangles angles sum to 180 degrees, the total is 360 degrees.', NULL, NULL),
(5454, 3, NULL, NULL, 3109, 'The square root of 144 is:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, '12 x 12 = 144, so the square root of 144 is 12.', NULL, NULL),
(5455, 3, NULL, NULL, 3109, 'The cube root of 216 is:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, '6 x 6 x 6 = 216, so the cube root of 216 is 6.', NULL, NULL),
(5456, 3, NULL, NULL, 3109, 'Simplify the algebraic expression: 3a + 2b - a + 5b.', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Combining like terms: (3a - a) + (2b + 5b) = 2a + 7b.', NULL, NULL),
(5457, 3, NULL, NULL, 3109, 'The area of a trapezium is calculated as half the sum of the parallel sides multiplied by the:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Area of a trapezium = 1/2 x (sum of parallel sides) x height, where height is the perpendicular distance between the two parallel sides.', NULL, NULL),
(5458, 3, NULL, NULL, 3109, 'The value of 2 raised to the power 5 (2^5) is:', '3', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, '2^5 = 2x2x2x2x2 = 32.', NULL, NULL),
(5459, 3, NULL, NULL, 3109, 'Which of the following is an irrational number?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The square root of 2 cannot be expressed as a simple fraction p/q and has a non-terminating, non-repeating decimal expansion, making it irrational.', NULL, NULL),
(5460, 3, NULL, NULL, 3109, 'The degree of the polynomial 4x^3 + 3x^2 - x + 7 is:', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The degree of a polynomial is the highest power of the variable present; here the highest power of x is 3.', NULL, NULL),
(5461, 3, NULL, NULL, 3109, 'The distance of the point (3, 4) from the origin in the Cartesian plane is:', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Using the distance formula (or Pythagoras theorem): sqrt(3^2 + 4^2) = sqrt(9+16) = sqrt(25) = 5.', NULL, NULL),
(5462, 3, NULL, NULL, 3109, 'The linear equation 2x + 3y = 6 has:', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A linear equation in two variables represents a straight line, and every point on that line is a solution, giving infinitely many solutions.', NULL, NULL),
(5463, 3, NULL, NULL, 3109, 'Euclids fifth postulate is closely related to the concept of:', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Euclids fifth postulate deals with the conditions under which two lines, when extended, will or will not meet, forming the basis of the concept of parallel lines.', NULL, NULL),
(5464, 3, NULL, NULL, 3109, 'If a transversal intersects two lines such that the sum of the interior angles on the same side is 180 degrees, the two lines are:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'By the co-interior angles axiom, if the sum of interior angles on the same side of a transversal is 180 degrees, the two lines are parallel.', NULL, NULL),
(5465, 3, NULL, NULL, 3109, 'In any triangle, the sum of the lengths of any two sides is always ______ the length of the third side.', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The triangle inequality theorem states that the sum of any two sides of a triangle must be greater than the length of the third side.', NULL, NULL),
(5466, 3, NULL, NULL, 3109, 'Herons formula is used to calculate the ______ of a triangle when the lengths of all three sides are known.', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Herons formula computes the area of a triangle directly from the lengths of its three sides without needing to know the height.', NULL, NULL),
(5467, 3, NULL, NULL, 3109, 'The total surface area of a cube with side length a is:', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A cube has 6 identical square faces, each with area a^2, so its total surface area is 6a^2.', NULL, NULL),
(5468, 3, NULL, NULL, 3109, 'Which of the following is an irrational number?', '3', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The square root of 7 is a non-terminating, non-repeating decimal and cannot be expressed as a ratio of integers, making it irrational, unlike the square roots of the perfect squares 4 and 9.', NULL, NULL),
(5469, 3, NULL, NULL, 3109, 'The zeroes of the polynomial x^2 - 5x + 6 are:', '1', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Factoring x^2 - 5x + 6 gives (x-2)(x-3) = 0, so the zeroes are x = 2 and x = 3.', NULL, NULL),
(5470, 3, NULL, NULL, 3109, 'A pair of linear equations in two variables that has no common solution is called:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'A pair of linear equations is called inconsistent when the lines they represent are parallel and never intersect, meaning there is no common solution.', NULL, NULL),
(5471, 3, NULL, NULL, 3109, 'For a quadratic equation ax^2 + bx + c = 0, if the discriminant (b^2 - 4ac) equals zero, the equation has:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'When the discriminant equals zero, the quadratic equation has two real roots that are equal (a repeated root).', NULL, NULL),
(5472, 3, NULL, NULL, 3109, 'In an Arithmetic Progression with first term 5 and common difference 3, the 4th term is:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The nth term of an A.P. is a + (n-1)d. For n=4: 5 + (4-1)x3 = 5 + 9 = 14.', NULL, NULL),
(5473, 3, NULL, NULL, 3109, 'Two triangles are said to be similar if their corresponding angles are equal and their corresponding sides are:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Similar triangles have equal corresponding angles and corresponding sides that are in the same proportion, though not necessarily equal in length.', NULL, NULL),
(5474, 3, NULL, NULL, 3109, 'The value of sin 30 degrees + cos 60 degrees is:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'sin 30 degrees = 1/2 and cos 60 degrees = 1/2, so their sum is 1/2 + 1/2 = 1.', NULL, NULL),
(5475, 3, NULL, NULL, 3109, 'The formula for the total surface area of a cylinder with radius r and height h is:', '1', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The total surface area of a cylinder equals the curved surface area (2*pi*r*h) plus the area of the two circular ends (2*pi*r^2), which simplifies to 2*pi*r*(r+h).', NULL, NULL),
(5476, 24, NULL, NULL, 3109, 'Growing the same or different crops in a planned sequence on the same piece of land over different seasons is called:', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Crop rotation involves growing different crops in a planned sequence on the same land to maintain soil fertility and reduce pest buildup.', NULL, NULL),
(5477, 24, NULL, NULL, 3109, 'Microorganisms that convert atmospheric nitrogen into a usable form in the soil, increasing its fertility, are called:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Nitrogen-fixing bacteria, such as Rhizobium found in root nodules of legumes, convert atmospheric nitrogen into compounds usable by plants.', NULL, NULL),
(5478, 24, NULL, NULL, 3109, 'The basic structural and functional unit of life is the:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The cell is considered the fundamental building block of all living organisms, capable of carrying out all basic life processes.', NULL, NULL),
(5479, 24, NULL, NULL, 3109, 'Which part of a cell controls all its activities and contains the genetic material?', '3', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The nucleus houses the cells DNA and acts as its control center, directing growth, metabolism, and reproduction.', NULL, NULL),
(5480, 24, NULL, NULL, 3109, 'The process by which a tadpole transforms into an adult frog is called:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Metamorphosis is the biological process of transformation from a larval stage (like a tadpole) into an adult form with a different body structure.', NULL, NULL),
(5481, 24, NULL, NULL, 3109, 'The stage of life during which the body undergoes changes leading to reproductive maturity is called:', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Adolescence is the transitional period between childhood and adulthood, marked by puberty and the attainment of reproductive maturity.', NULL, NULL),
(5482, 24, NULL, NULL, 3109, 'Which cell organelle is known as the \"powerhouse of the cell\"?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Mitochondria generate most of the cells energy (ATP) through cellular respiration, earning them the nickname \"powerhouse of the cell.\"', NULL, NULL),
(5483, 24, NULL, NULL, 3109, 'Which plant tissue is mainly responsible for the transport of water and minerals from roots to other parts of the plant?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Xylem tissue conducts water and dissolved minerals upward from the roots to the stem, leaves, and other plant parts.', NULL, NULL),
(5484, 24, NULL, NULL, 3109, 'The five-kingdom classification of living organisms was proposed by:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'R.H. Whittaker proposed the five-kingdom classification system in 1969, grouping organisms into Monera, Protista, Fungi, Plantae, and Animalia.', NULL, NULL),
(5485, 24, NULL, NULL, 3109, 'Diseases that spread from an infected person to a healthy person through air, water, or contact are called:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Communicable (infectious) diseases are caused by pathogens and can be transmitted from an infected individual to a healthy one.', NULL, NULL),
(5486, 24, NULL, NULL, 3109, 'Which of the following is a non-renewable natural resource?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Fossil fuels take millions of years to form and are being consumed much faster than they are replenished, making them non-renewable, unlike sunlight, wind, and rainwater.', NULL, NULL),
(5487, 24, NULL, NULL, 3109, 'The layer of the atmosphere that protects the Earth from harmful ultraviolet radiation is the:', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The ozone layer, located in the stratosphere, absorbs most of the suns harmful ultraviolet (UV) radiation, protecting life on Earth.', NULL, NULL),
(5488, 24, NULL, NULL, 3109, 'Hybridization in agriculture refers to the process of:', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Hybridization involves crossbreeding genetically different varieties or species to produce offspring with combined desirable characteristics.', NULL, NULL),
(5489, 24, NULL, NULL, 3109, 'Which simple plant tissue, containing chloroplasts, is mainly responsible for carrying out photosynthesis?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Chlorenchyma, a type of parenchyma tissue containing chloroplasts, is the primary site of photosynthesis in plants.', NULL, NULL),
(5490, 24, NULL, NULL, 3109, 'Amoeba and Paramecium belong to which kingdom of classification?', '2', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Amoeba and Paramecium are single-celled eukaryotic organisms classified under the kingdom Protista.', NULL, NULL),
(5491, 24, NULL, NULL, 3109, 'The basic structural and functional unit of the kidney, responsible for filtering blood, is called the:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The nephron is the microscopic filtering unit of the kidney that removes waste products and excess substances from the blood to form urine.', NULL, NULL),
(5492, 24, NULL, NULL, 3109, 'The rapid closing of the leaves of the \"touch-me-not\" (Mimosa) plant in response to touch is an example of:', '3', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Thigmonasty is a rapid, non-directional plant movement triggered by touch, seen classically in the sensitive \"touch-me-not\" plant.', NULL, NULL),
(5493, 24, NULL, NULL, 3109, 'The hormone that regulates blood sugar levels and is secreted by the pancreas is:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Insulin, secreted by the pancreas, regulates blood glucose levels by promoting the uptake of glucose into cells.', NULL, NULL),
(5494, 24, NULL, NULL, 3109, 'Which mode of reproduction involves the fusion of male and female gametes to form a new individual?', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Sexual reproduction involves the fusion (fertilization) of male and female gametes, producing offspring with genetic variation from both parents.', NULL, NULL),
(5495, 24, NULL, NULL, 3109, 'In humans, the sex of a child is determined by the sex chromosome contributed by the father, which can be:', '3', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'The mother always contributes an X chromosome; the father contributes either an X or a Y chromosome, which determines whether the child is female (XX) or male (XY).', NULL, NULL),
(5496, 24, NULL, NULL, 3109, 'The units of heredity that carry genetic information from parents to offspring are called:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Genes, segments of DNA located on chromosomes, are the basic units of heredity that determine inherited traits.', NULL, NULL),
(5497, 24, NULL, NULL, 3109, 'Charles Darwins theory of evolution is primarily based on the concept of:', '2', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Darwins theory of evolution centers on natural selection, where organisms better adapted to their environment are more likely to survive and reproduce.', NULL, NULL),
(5498, 24, NULL, NULL, 3109, 'The process by which green plants prepare their own food using sunlight, carbon dioxide, and water is called:', '3', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Photosynthesis is the process by which green plants use sunlight, carbon dioxide, and water to synthesize glucose and release oxygen.', NULL, NULL),
(5499, 24, NULL, NULL, 3109, 'A food chain always begins with:', '3', 'N', NULL, NULL, 'N', 'Hard', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Food chains start with producers, typically green plants, which convert solar energy into chemical energy through photosynthesis.', NULL, NULL),
