(803097, 103, NULL, NULL, 3130, 'Sri Ramadasu (2006) brought together which real-life father-and-son actors on screen?', '1', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Sri Ramadasu (2006), directed by K. Raghavendra Rao with music by M. M. Keeravani, featured Akkineni Nageswara Rao alongside his son Nagarjuna.', NULL, NULL),
(803098, 103, NULL, NULL, 3130, 'Which director made Prabhas\'s 2004 romantic hit Varsham, opposite Trisha?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Varsham (2004), with music by Devi Sri Prasad, was directed by Sobhan and became a breakthrough hit for Prabhas.', NULL, NULL),
(803099, 103, NULL, NULL, 3130, 'Prabhas played a dual role in Billa (2009), a remake of a Tamil film that was itself a remake of which classic Hindi film?', '3', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Billa (2009) remade the 2007 Tamil film Billa, which itself traced back to the 1978 Hindi classic Don.', NULL, NULL),
(803100, 103, NULL, NULL, 3130, 'Who composed the music for Billa (2009), starring Prabhas in a dual role?', '4', 'N', NULL, NULL, 'N', 'Medium', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Mani Sharma composed the score for Billa (2009), directed by Meher Ramesh.', NULL, NULL),
(803101, 103, NULL, NULL, 3130, 'Who directed Baahubali: The Beginning (2015)?', '1', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'S. S. Rajamouli wrote and directed Baahubali: The Beginning, released on 10 July 2015.', NULL, NULL),
(803102, 103, NULL, NULL, 3130, 'Which actor played the dual role of Shivudu and Amarendra Baahubali in the Baahubali films?', '2', 'N', NULL, NULL, 'N', 'Easy', 'Y', 'N', NULL, NULL, 'MCQ', 4, 'Prabhas played both Amarendra Baahubali and his son Mahendra Baahubali (Shivudu) across the two films.', NULL, NULL),
