INSERT INTO `tickets` (`TicketId`, `TicketNo`, `UserId`, `CategoryId`, `Subject`, `Description`, `Priority`, `Status`, `AssignedTo`, `SlaDeadline`, `ResolutionDue`, `FirstRepliedAt`, `ResolvedAt`, `ClosedAt`, `CreatedAt`, `UpdatedAt`) VALUES
(1, 'TKT-000001', 539, 5, 'Subject filter is not functioning in Browse & Enroll', 'In the Browse & Enroll section, selecting a subject from the Subject filter does not display the corresponding subject-related exams or courses. The content remains unchanged regardless of the selected subject, indicating that the filter is not working as expected.\r\n\r\nExpected Behavior:\r\nWhen a user selects a subject, only the exams or courses related to that subject should be displayed.', 'high', 'open', NULL, '2026-08-03 01:12:07', '2026-08-04 01:12:07', NULL, NULL, NULL, '2026-08-02 13:12:07', '2026-08-02 13:12:07'),
(2, 'TKT-000002', 539, 1, 'Instructions option redirects to the wrong page', 'In the My Exams section, clicking the Instructions option for an exam redirects the user to the Upcoming Exams / Browse & Enroll page instead of displaying the instructions for the selected exam.\r\n\r\nExpected Behavior:\r\nClicking Instructions should open the instruction page for the selected exam without redirecting the user to a different section of the application.', 'high', 'open', NULL, '2026-08-02 15:12:50', '2026-08-03 01:12:50', NULL, NULL, NULL, '2026-08-02 13:12:50', '2026-08-02 13:12:50'),
(3, 'TKT-000003', 539, 3, 'Phone number validation fails due to automatic +91 prefix', 'In Profile → Account Settings, the phone number field displays a validation error stating that the number must contain 10 digits. However, the application automatically prefixes the number with +91, causing the validation to fail even when the entered phone number is correct.\r\n\r\nExpected Behavior:\r\nThe validation should ignore the country code or correctly validate phone numbers that include the +91 prefix.', 'medium', 'open', NULL, '2026-08-02 21:13:22', '2026-08-04 13:13:22', NULL, NULL, NULL, '2026-08-02 13:13:22', '2026-08-02 13:13:22');
