CREATE DEFINER=`u304752530_mcquser`@`127.0.0.1` PROCEDURE `_create_chapter_exams_from_exam` (IN `p_source_exam_id` INT)   BEGIN
    DECLARE v_new_exam_count INT DEFAULT 0;
    DECLARE v_linked_count   INT DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- Guard: source exam must exist.
    IF NOT EXISTS (SELECT 1 FROM examinfo WHERE ExamInfoId = p_source_exam_id) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'create_chapter_exams_from_exam: source ExamInfoId not found in examinfo';
    END IF;

    -- ── Step 1: one new exam per chapter found, scaled to that chapter's actual question count ──
    -- GROUP BY c.ChapterInfoId + COUNT(*) drive everything below: however many
    -- distinct chapters and however many questions per chapter the source exam
    -- actually has, this produces exactly that many rows, sized exactly that way.
       NumOfQuestions, MinPassing, TimeAlloted,
       ExamScope, ExamInstituteId, ExamFreeFor, ExamFee, ExamDiscountPct,
       IsActive, MaxAttempts, MarkingScheme, TotalMarks, MarksPerQuestion,
       NegativeMarks, ExamCategory, proctor_lock)
    SELECT
       CONCAT(src.ExamName, ' - ', c.ChapterName)                          AS ExamName,
       src.Language, src.GradeInfoId, src.SubjectInfoId, src.IsMultiSubject,
       COUNT(*)                                                            AS NumOfQuestions,
       ROUND(src.MinPassing  * COUNT(*) / src.NumOfQuestions, 2)           AS MinPassing,
       GREATEST(1, ROUND(src.TimeAlloted * COUNT(*) / src.NumOfQuestions)) AS TimeAlloted,
       src.ExamScope, src.ExamInstituteId, src.ExamFreeFor, src.ExamFee, src.ExamDiscountPct,
       'Y', src.MaxAttempts, src.MarkingScheme,
       ROUND(src.TotalMarks * COUNT(*) / src.NumOfQuestions, 2)            AS TotalMarks,
       src.MarksPerQuestion, src.NegativeMarks, src.ExamCategory, src.proctor_lock
    FROM exam_questions eq
    JOIN questions   q   ON q.QuestionId    = eq.QuestionId
    JOIN chapterinfo c   ON c.ChapterInfoId = q.ChapterInfoId
                        AND c.SubjectInfoId = q.SubjectInfoId
    JOIN examinfo    src ON src.ExamInfoId  = p_source_exam_id
    WHERE eq.ExamInfoId    = p_source_exam_id
      AND eq.IsActive      = 'Y'
      AND q.IsDeleted      = 'N'
      AND q.IsActive       = 'Y'
      AND q.ChapterInfoId IS NOT NULL
      AND NOT EXISTS (
            SELECT 1 FROM examinfo e2
             WHERE e2.ExamName = CONCAT(src.ExamName, ' - ', c.ChapterName)
          )
    GROUP BY c.ChapterInfoId, c.ChapterName,
             src.ExamName, src.Language, src.GradeInfoId, src.SubjectInfoId, src.IsMultiSubject,
             src.MinPassing, src.TimeAlloted, src.NumOfQuestions, src.ExamScope, src.ExamInstituteId,
             src.ExamFreeFor, src.ExamFee, src.ExamDiscountPct, src.MaxAttempts, src.MarkingScheme,
             src.TotalMarks, src.MarksPerQuestion, src.NegativeMarks, src.ExamCategory, src.proctor_lock;

    SET v_new_exam_count = ROW_COUNT();

    -- ── Step 2: link every question to its matching new chapter exam ──
    -- One set-based INSERT for every chapter at once (no per-chapter loop) --
    -- works identically whether the source exam has 3 chapters or 300.
    SELECT ne.ExamInfoId, eq.QuestionId, eq.IsActive
    FROM exam_questions eq
    JOIN questions   q   ON q.QuestionId    = eq.QuestionId
    JOIN chapterinfo c   ON c.ChapterInfoId = q.ChapterInfoId
                        AND c.SubjectInfoId = q.SubjectInfoId
    JOIN examinfo    src ON src.ExamInfoId  = p_source_exam_id
    JOIN examinfo    ne  ON ne.ExamName     = CONCAT(src.ExamName, ' - ', c.ChapterName)
    WHERE eq.ExamInfoId    = p_source_exam_id
      AND eq.IsActive      = 'Y'
      AND q.IsDeleted      = 'N'
      AND q.IsActive       = 'Y'
      AND q.ChapterInfoId IS NOT NULL
      AND NOT EXISTS (
            SELECT 1 FROM exam_questions eq2
             WHERE eq2.ExamInfoId = ne.ExamInfoId AND eq2.QuestionId = eq.QuestionId
          );

    SET v_linked_count = ROW_COUNT();

    COMMIT;

    SELECT v_new_exam_count AS NewExamsCreated, v_linked_count AS QuestionsLinked;
END$$

CREATE DEFINER=`u304752530_mcquser`@`127.0.0.1` PROCEDURE `_neet_physics_import_batch1` ()   BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SET @subjectId := (SELECT SubjectInfoId FROM subjectinfo WHERE SubjectName = 'Physics' LIMIT 1);
    SET @examId    := (SELECT ExamInfoId    FROM examinfo    WHERE ExamName = 'NEET/JEE Bank – Physics' LIMIT 1);

    IF @subjectId IS NULL OR @examId IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Physics subject or NEET/JEE Bank – Physics exam not found - run neet_physics.sql first. No base-table rows are created by this script.';
    END IF;

       CorrectAnswer, Complexity, IsActive, Explanation, OperatorInd, ImageInd)
    VALUES
    (110001,@subjectId,50101,@examId,'The SI unit of luminous intensity is:','MCQ','2','Easy','Y','Candela (cd) is the SI base unit of luminous intensity.','N','N'),
    (110002,@subjectId,50101,@examId,'Which of these is a fundamental (base) quantity in the SI system?','MCQ','3','Easy','Y','Electric current (ampere) is one of the 7 SI base quantities; force, velocity, momentum are derived.','N','N'),
    (110003,@subjectId,50101,@examId,'The dimensional formula of force is:','MCQ','2','Easy','Y','F=ma, [M][LT^-2]=[MLT^-2].','N','N'),
    (110004,@subjectId,50101,@examId,'Dimensional formula of work is:','MCQ','2','Easy','Y','Work=Force x distance = [MLT^-2][L]=[ML^2T^-2].','N','N'),
    (110005,@subjectId,50101,@examId,'Which pair has DIFFERENT dimensions from each other?','MCQ','4','Medium','Y','Impulse=momentum [MLT^-1]; Work=Energy [ML^2T^-2]; Pressure=Stress [ML^-1T^-2] — all matching pairs. Force [MLT^-2] and Energy [ML^2T^-2] differ.','N','N'),
    (110006,@subjectId,50101,@examId,'The number of significant figures in 0.070060 is:','MCQ','3','Medium','Y','Leading zeros aren''t significant; 7,0,0,6,0 counted from first nonzero digit = 5 significant figures.','N','N'),
    (110007,@subjectId,50101,@examId,'A physical quantity P = a^2 b^3 / c. If percentage errors in a, b, c are 1%, 2%, 3%, error in P is:','MCQ','3','Medium','Y','%error in P = 2(%a)+3(%b)+%c = 2(1)+3(2)+3 = 2+6+3=11%.','N','N'),
    (110008,@subjectId,50101,@examId,'The least count of a screw gauge with pitch 1 mm and 100 divisions is:','MCQ','2','Easy','Y','Least count = pitch/divisions = 1/100 = 0.01 mm.','N','N'),
    (110009,@subjectId,50101,@examId,'Parallax method is used to measure:','MCQ','2','Easy','Y','Parallax uses angular shift viewed from two points to estimate large distances like to stars/planets.','N','N'),
    (110010,@subjectId,50101,@examId,'1 light year is a unit of:','MCQ','2','Easy','Y','A light year is the distance light travels in one year — a unit of distance/length.','N','N'),
    (110011,@subjectId,50101,@examId,'The dimensions of Planck''s constant are the same as those of:','MCQ','3','Medium','Y','E=hv => h=E/v, [ML^2T^-2]/[T^-1]=[ML^2T^-1], same as angular momentum L=mvr.','N','N'),
    (110012,@subjectId,50101,@examId,'Which of the following is dimensionless?','MCQ','1','Easy','Y','Strain = change in length/original length, a ratio of two lengths, hence dimensionless.','N','N'),
    (110013,@subjectId,50101,@examId,'The order of magnitude of the mass of an electron is:','MCQ','1','Medium','Y','Electron mass is about 9.1x10^-31 kg.','N','N'),
    (110014,@subjectId,50101,@examId,'A vernier caliper has 10 vernier divisions equal to 9 main scale divisions of 1mm each. Its vernier constant is:','MCQ','2','Easy','Y','VC = 1 MSD - 1 VSD = 1mm - 0.9mm = 0.1mm.','N','N'),
    (110015,@subjectId,50101,@examId,'Which of the following measurements has the maximum number of significant figures?','MCQ','1','Medium','Y','6.20 has 3 significant figures (6,2,0-trailing after decimal is significant); others: 0.0062 has 2 sig figs; 6.2x10^2 has 2; 62000 (ambiguous, typically 2) — so 6.20 has most among these.','N','N'),
    (110016,@subjectId,50101,@examId,'The dimensional formula for coefficient of viscosity is:','MCQ','1','Hard','Y','From F=6*pi*eta*r*v (Stokes law), eta = F/(r v), dimension works out to [ML^-1T^-1].','N','N'),
    (110017,@subjectId,50101,@examId,'Absolute error is best defined as:','MCQ','2','Easy','Y','Absolute error = |true value - measured value|, expressed in the same units as the quantity.','N','N'),
    (110018,@subjectId,50101,@examId,'Which instrument is best suited to measure the diameter of a thin wire precisely?','MCQ','3','Easy','Y','A screw gauge has a much smaller least count (~0.01mm), ideal for thin wires.','N','N'),
    (110019,@subjectId,50101,@examId,'The dimensional formula of angular velocity is:','MCQ','1','Easy','Y','Angular velocity = angle/time, angle is dimensionless, so [omega]=[T^-1].','N','N'),
    (110020,@subjectId,50101,@examId,'If momentum (P), area (A), and time (T) are taken as fundamental quantities, the dimensional formula of energy would be:','MCQ','1','Hard','Y','Energy=[ML^2T^-2]; expressing in terms of P=[MLT^-1], A=[L^2], T=[T] and solving gives E = P^2 A^-1 T^-2 up to constants (standard derivation).','N','N'),
    (110021,@subjectId,50101,@examId,'The number of base SI units is:','MCQ','3','Easy','Y','There are 7 SI base units: metre, kilogram, second, ampere, kelvin, mole, candela.','N','N'),
    (110022,@subjectId,50101,@examId,'Systematic errors can be reduced by:','MCQ','2','Medium','Y','Systematic errors are consistent/biased errors caused by faulty instruments/technique, reduced by calibration, not just averaging (which reduces random error).','N','N'),
    (110023,@subjectId,50101,@examId,'A dimensionally consistent equation guarantees that the equation is:','MCQ','2','Medium','Y','Dimensional consistency is necessary but not sufficient for physical correctness (dimensionless constants can''t be checked this way).','N','N'),
    (110024,@subjectId,50101,@examId,'The SI unit of pressure, the pascal, is dimensionally equivalent to:','MCQ','2','Easy','Y','Pressure = Force/Area, Pa = N/m^2.','N','N'),
    (110025,@subjectId,50101,@examId,'Percentage error in the measurement of radius of a sphere is 1%. The percentage error in its volume is:','MCQ','3','Medium','Y','V ∝ r^3, so %error in V = 3 x %error in r = 3 x 1% = 3%.','N','N'),
    (110026,@subjectId,50101,@examId,'Which of the following pairs does NOT have the same dimensions?','MCQ','4','Medium','Y','Power=[ML^2T^-3], Force=[MLT^-2] — different dimensions, unlike the other pairs which do match.','N','N'),
    (110027,@subjectId,50101,@examId,'A resistor''s value is 12.4 ± 0.2 ohm. Percentage error in resistance is approximately:','MCQ','2','Medium','Y','%error = (0.2/12.4)x100 ≈ 1.6%.','N','N'),
    (110028,@subjectId,50101,@examId,'The number of significant figures in the measurement 4.700 x 10^-3 kg is:','MCQ','4','Medium','Y','All digits 4,7,0,0 are significant since it''s expressed in scientific notation.','N','N'),
    (110029,@subjectId,50101,@examId,'Which quantity has dimensions [M^0L^0T^0] (dimensionless)?','MCQ','1','Easy','Y','Refractive index is a ratio of speeds and is dimensionless.','N','N'),
    (110030,@subjectId,50101,@examId,'The unit ''parsec'' is used to measure:','MCQ','2','Easy','Y','A parsec (~3.26 light years) is a unit of astronomical distance.','N','N'),
    (110031,@subjectId,50101,@examId,'If the unit of length and time are doubled, the unit of velocity will:','MCQ','1','Medium','Y','Velocity=L/T; doubling both L and T leaves the ratio (and hence numerical unit scaling) unchanged.','N','N'),
    (110032,@subjectId,50101,@examId,'A student measures the diameter of a wire as 1.25, 1.26, 1.24, 1.27, 1.23 mm in 5 trials. The mean value is:','MCQ','2','Easy','Y','Mean = (1.25+1.26+1.24+1.27+1.23)/5 = 6.25/5 = 1.25 mm.','N','N'),
    (110033,@subjectId,50101,@examId,'Zero error in a screw gauge is accounted for by:','MCQ','2','Medium','Y','Correct reading = observed reading − (zero error), with the zero error''s own sign taken into account.','N','N'),
    (110034,@subjectId,50101,@examId,'Which of the following has the dimension of frequency?','MCQ','1','Medium','Y','RC has dimension of time, so 1/RC has dimension of frequency [T^-1].','N','N'),
    (110035,@subjectId,50101,@examId,'The precision of a measurement refers to:','MCQ','2','Easy','Y','Precision reflects consistency/reproducibility of measurements, distinct from accuracy (closeness to true value).','N','N'),
    (110036,@subjectId,50101,@examId,'Dimensional analysis cannot be used to derive relations involving:','MCQ','1','Medium','Y','Dimensional analysis cannot determine dimensionless numerical constants or the functional form for trigonometric/exponential/logarithmic dependencies.','N','N'),
    (110037,@subjectId,50101,@examId,'The dimensional formula of surface tension is:','MCQ','1','Medium','Y','Surface tension = Force/length = [MLT^-2]/[L] = [MT^-2].','N','N'),
    (110038,@subjectId,50101,@examId,'A light-year is approximately equal to:','MCQ','2','Medium','Y','1 light year = c x 1 year ≈ 9.46 x 10^15 metres.','N','N'),
    (110039,@subjectId,50101,@examId,'The order of magnitude of the radius of a hydrogen atom is:','MCQ','1','Medium','Y','The Bohr radius (hydrogen atom size) is about 0.53 x 10^-10 m, order of magnitude 10^-10 m.','N','N'),
    (110040,@subjectId,50101,@examId,'Which error type arises due to random, unpredictable fluctuations in observations?','MCQ','2','Easy','Y','Random errors arise from unpredictable variations and are reduced by taking the mean of many readings.','N','N'),
    (110041,@subjectId,50101,@examId,'Density has the dimensional formula:','MCQ','1','Easy','Y','Density = mass/volume = [M]/[L^3] = [ML^-3].','N','N'),
    (110042,@subjectId,50101,@examId,'The SI unit of thermal conductivity has dimensions of:','MCQ','1','Hard','Y','Thermal conductivity k in Q=kAΔT/d has SI dimensional formula [MLT^-3K^-1] (Watts per metre per Kelvin).','N','N'),
    (110043,@subjectId,50101,@examId,'A measurement recorded as 25.0 cm implies the instrument''s least count allows precision to:','MCQ','3','Medium','Y','Writing 25.0 (with one decimal) implies the measuring instrument could resolve to 0.1 cm.','N','N'),
    (110044,@subjectId,50101,@examId,'Two quantities can be added or subtracted only if they have:','MCQ','2','Easy','Y','Only quantities with identical dimensions can be meaningfully added or subtracted (principle of dimensional homogeneity).','N','N'),
    (110045,@subjectId,50101,@examId,'The dimensional formula of the universal gas constant R is:','MCQ','1','Hard','Y','From PV=nRT, R = PV/(nT), dimensionally [ML^2T^-2K^-1mol^-1] (energy per mole per kelvin).','N','N'),
    (110046,@subjectId,50101,@examId,'If 1% error is allowed in the measurement of the side of a cube, error in its volume will be about:','MCQ','3','Medium','Y','V ∝ side^3, so %error in V = 3 x 1% = 3%.','N','N'),
    (110047,@subjectId,50101,@examId,'Accuracy of a measurement refers to:','MCQ','1','Easy','Y','Accuracy is how close a measured value is to the actual/true value, distinct from precision (consistency).','N','N'),
    (110048,@subjectId,50101,@examId,'The dimensions of specific heat capacity are:','MCQ','1','Medium','Y','Specific heat c in Q=mcΔT gives c = Q/(mΔT), dimension [L^2T^-2K^-1] (per unit mass already divided out).','N','N'),
    (110049,@subjectId,50101,@examId,'A physical quantity that has the same dimension in all systems of units is a:','MCQ','3','Medium','Y','Dimensionless quantities (like refractive index, strain, angle) have the same ''dimension'' (none) regardless of the unit system used.','N','N'),
    (110050,@subjectId,50101,@examId,'Round off 6.3287 to 3 significant figures:','MCQ','1','Easy','Y','6.3287 rounded to 3 significant figures: examine the 4th digit (8) to round up the 3rd digit: 6.33.','N','N'),
    (110051,@subjectId,50101,@examId,'Which of these represents a derived unit?','MCQ','3','Easy','Y','The newton (force) is derived from kg.m/s^2; kilogram, second, and ampere are all SI base units.','N','N'),
    (110101,@subjectId,50102,@examId,'A car accelerates uniformly from rest to 20 m/s in 5 s. Its acceleration is:','MCQ','2','Easy','Y','a=(v-u)/t=(20-0)/5=4 m/s^2.','N','N'),
    (110102,@subjectId,50102,@examId,'A body moving with uniform velocity has:','MCQ','2','Easy','Y','Uniform velocity means constant speed and direction, so acceleration is zero.','N','N'),
    (110103,@subjectId,50102,@examId,'The area under a velocity-time graph gives:','MCQ','2','Easy','Y','Area under v-t graph = integral of v dt = displacement.','N','N'),
    (110104,@subjectId,50102,@examId,'A ball is thrown vertically upward with speed u. Time to reach maximum height is:','MCQ','1','Easy','Y','At max height v=0: 0=u-gt => t=u/g.','N','N'),
    (110105,@subjectId,50102,@examId,'The slope of a position-time graph gives:','MCQ','2','Easy','Y','Slope of x-t graph = dx/dt = instantaneous velocity.','N','N'),
    (110106,@subjectId,50102,@examId,'A stone dropped from a height h reaches the ground in time t. If dropped from height 4h, time taken is:','MCQ','2','Medium','Y','h ∝ t^2, so quadrupling h doubles t (since sqrt(4)=2).','N','N'),
    (110107,@subjectId,50102,@examId,'Which of the following can be negative: distance or displacement?','MCQ','2','Easy','Y','Displacement is a vector and can be negative (opposite to chosen positive direction); distance (path length) is always non-negative.','N','N'),
    (110108,@subjectId,50102,@examId,'A particle moves in a straight line with constant acceleration. Its velocity-time graph is:','MCQ','2','Easy','Y','v=u+at is linear in t, so the v-t graph is a straight line for constant acceleration.','N','N'),
    (110109,@subjectId,50102,@examId,'A body thrown horizontally from a height h with speed u hits the ground in time:','MCQ','2','Medium','Y','Vertical motion is independent of horizontal: h=(1/2)gt^2 => t=sqrt(2h/g).','N','N'),
    (110110,@subjectId,50102,@examId,'For a projectile launched at angle theta with speed u, the range is maximum when theta equals:','MCQ','2','Easy','Y','Range R=u^2 sin(2theta)/g is maximum when sin(2theta)=1, i.e. theta=45°.','N','N'),
    (110111,@subjectId,50102,@examId,'The maximum height attained by a projectile launched at angle theta with speed u is:','MCQ','1','Medium','Y','H = (u sin theta)^2 / (2g) = u^2 sin^2(theta)/(2g).','N','N'),
    (110112,@subjectId,50102,@examId,'Two projectiles launched at angles theta and (90°-theta) with the same speed have:','MCQ','1','Medium','Y','R depends on sin(2theta), which is same for theta and 90-theta (complementary angles); max heights differ since they depend on sin^2(theta).','N','N'),
    (110113,@subjectId,50102,@examId,'A particle has initial velocity 10 m/s and constant acceleration -2 m/s^2. Its velocity becomes zero after:','MCQ','2','Easy','Y','v=u+at => 0=10-2t => t=5s.','N','N'),
    (110114,@subjectId,50102,@examId,'Displacement of a particle moving with constant acceleration is given by s=ut+(1/2)at^2. This equation assumes:','MCQ','2','Easy','Y','This is the standard second equation of motion, valid for constant acceleration in one dimension, u need not be zero.','N','N'),
    (110115,@subjectId,50102,@examId,'A body''s velocity-time graph is a straight line parallel to the time axis. This indicates:','MCQ','2','Easy','Y','A horizontal v-t line means velocity is constant (uniform), i.e., zero acceleration.','N','N'),
    (110116,@subjectId,50102,@examId,'Relative velocity of A with respect to B is given by:','MCQ','2','Easy','Y','Relative velocity of A w.r.t B = vA - vB (vector subtraction).','N','N'),
    (110117,@subjectId,50102,@examId,'A boat crosses a river of width d with velocity v perpendicular to the flow of the river (velocity u). Time to cross is:','MCQ','1','Medium','Y','The perpendicular component of velocity (v) alone determines time to cross: t=d/v, independent of current u.','N','N'),
    (110118,@subjectId,50102,@examId,'The average velocity of a body during its entire journey, if it returns to the starting point, is:','MCQ','2','Easy','Y','Since net displacement is zero when returning to start, average velocity (displacement/time) is zero, though average speed (distance/time) is non-zero.','N','N'),
    (110119,@subjectId,50102,@examId,'A car travels first half of a distance at speed v1 and second half at speed v2. Its average speed is:','MCQ','2','Medium','Y','For equal distances at two speeds, average speed = harmonic mean = 2v1v2/(v1+v2).','N','N'),
    (110120,@subjectId,50102,@examId,'A particle undergoes uniform circular motion. Which quantity remains constant?','MCQ','2','Easy','Y','In uniform circular motion, speed (magnitude of velocity) stays constant, but velocity direction and acceleration direction continuously change.','N','N'),
    (110121,@subjectId,50102,@examId,'The centripetal acceleration of a particle in uniform circular motion of radius r and speed v is:','MCQ','2','Easy','Y','Centripetal acceleration a=v^2/r, directed towards the centre.','N','N'),
    (110122,@subjectId,50102,@examId,'A projectile''s horizontal velocity during flight (ignoring air resistance):','MCQ','3','Easy','Y','With no air resistance, there''s no horizontal force, so horizontal velocity component remains constant throughout the flight.','N','N'),
    (110123,@subjectId,50102,@examId,'Time of flight of a projectile launched at angle theta with speed u is:','MCQ','2','Medium','Y','T = 2u sin(theta)/g, derived from vertical motion returning to same height.','N','N'),
    (110124,@subjectId,50102,@examId,'A particle''s position is x=5t^2+3t+2 (in SI units). Its acceleration is:','MCQ','3','Medium','Y','v=dx/dt=10t+3, a=dv/dt=10 m/s^2 (constant).','N','N'),
    (110125,@subjectId,50102,@examId,'If a body covers equal distances in equal intervals of time, its motion is termed:','MCQ','2','Easy','Y','Equal distances in equal time intervals defines uniform (constant speed) motion.','N','N'),
    (110126,@subjectId,50102,@examId,'A ball dropped from height h reaches the ground with speed:','MCQ','2','Easy','Y','Using v^2=u^2+2gh with u=0: v=sqrt(2gh).','N','N'),
    (110127,@subjectId,50102,@examId,'The instantaneous velocity of an object is defined as:','MCQ','2','Medium','Y','Instantaneous velocity = lim(Δt→0) Δx/Δt = dx/dt, the derivative of position with respect to time.','N','N'),
    (110128,@subjectId,50102,@examId,'A projectile is fired at 45° to maximize range. At the highest point of its trajectory, its velocity is:','MCQ','3','Medium','Y','At max height, vertical velocity component is zero; only the horizontal component (u cos theta) remains, which is the speed at that point.','N','N'),
    (110129,@subjectId,50102,@examId,'The dimension of jerk (rate of change of acceleration) is:','MCQ','3','Hard','Y','Jerk = da/dt, [LT^-2]/[T] = [LT^-3].','N','N'),
    (110130,@subjectId,50102,@examId,'A body starts from rest and moves with constant acceleration a. The distance covered in the nth second is proportional to:','MCQ','2','Medium','Y','Distance in nth second Sn = u + a(2n-1)/2; for u=0, Sn ∝ (2n-1).','N','N'),
    (110131,@subjectId,50102,@examId,'A particle moving in a straight line covers half the total distance with speed v1 and the other half of TIME with speeds v2 and v3 equally split. This scenario tests understanding that average speed depends on whether splitting is by:','MCQ','1','Medium','Y','When distance is split equally use harmonic mean; when time is split equally use arithmetic mean of speeds — the method of splitting changes the formula used.','N','N'),
    (110132,@subjectId,50102,@examId,'A car moving at 72 km/h is brought to rest by brakes in 5 seconds. The retardation is:','MCQ','1','Medium','Y','72 km/h=20 m/s; a=(0-20)/5=-4 m/s^2, retardation magnitude 4 m/s^2.','N','N'),
    (110133,@subjectId,50102,@examId,'Two balls are thrown from the same point, one straight up and one at an angle, with the same initial speed. Which stays in the air longer (assuming both return to launch height)?','MCQ','1','Medium','Y','Time of flight for vertical throw = 2u/g, which is greater than 2u sin(theta)/g for any theta<90° (angled throw has less vertical velocity component).','N','N'),
    (110134,@subjectId,50102,@examId,'A lift is moving up with acceleration a. The apparent weight of a person of mass m inside is:','MCQ','2','Easy','Y','When accelerating upward, normal force (apparent weight) N=m(g+a) by Newton''s second law on the person.','N','N'),
    (110135,@subjectId,50102,@examId,'If a body is projected vertically upward, its acceleration at the highest point is:','MCQ','2','Easy','Y','Acceleration due to gravity acts throughout the flight, including at the highest point, directed downward, magnitude g.','N','N'),
    (110136,@subjectId,50102,@examId,'A particle moves along the x-axis such that its velocity v = 3t^2 - 6t (SI units). It is momentarily at rest at t=0 and t=:','MCQ','2','Medium','Y','v=0 => 3t^2-6t=0 => 3t(t-2)=0 => t=0 or t=2s.','N','N'),
    (110137,@subjectId,50102,@examId,'The trajectory of a projectile (neglecting air resistance) is a:','MCQ','3','Easy','Y','Combining uniform horizontal motion with uniformly accelerated vertical motion produces a parabolic path.','N','N'),
    (110138,@subjectId,50102,@examId,'A cyclist moving at constant speed goes around a circular track. The work done by centripetal force is:','MCQ','3','Easy','Y','Centripetal force is always perpendicular to velocity/displacement, so it does zero work.','N','N'),
    (110139,@subjectId,50102,@examId,'For two vectors of equal magnitude A, the magnitude of their resultant is maximum when the angle between them is:','MCQ','1','Easy','Y','Resultant magnitude = sqrt(A^2+A^2+2A^2 cos theta), maximized when cos theta=1, i.e., theta=0° (vectors aligned).','N','N'),
    (110140,@subjectId,50102,@examId,'The resultant of two vectors of equal magnitude A acting at 120° to each other has magnitude:','MCQ','2','Medium','Y','R=sqrt(A^2+A^2+2A^2cos120°)=sqrt(2A^2-A^2)=sqrt(A^2)=A (since cos120°=-0.5).','N','N'),
    (110141,@subjectId,50102,@examId,'A body moving with constant speed in a circle experiences:','MCQ','2','Easy','Y','Even with constant speed, direction of velocity changes continuously, producing centripetal acceleration v^2/r toward the centre.','N','N'),
    (110142,@subjectId,50102,@examId,'A person walks 3m east then 4m north. The magnitude of net displacement is:','MCQ','3','Easy','Y','By Pythagoras, resultant = sqrt(3^2+4^2)=sqrt(25)=5 m.','N','N'),
    (110143,@subjectId,50102,@examId,'If the position vector of a particle is r=(3t)i+(4t)j (SI units), its speed is:','MCQ','3','Medium','Y','vx=3, vy=4, speed=sqrt(3^2+4^2)=5 m/s.','N','N'),
    (110144,@subjectId,50102,@examId,'A ball is thrown up with speed 20 m/s. Taking g=10 m/s^2, it returns to the thrower''s hand after:','MCQ','3','Easy','Y','Time of flight = 2u/g = 2x20/10=4 s.','N','N'),
    (110145,@subjectId,50102,@examId,'A particle moving with uniform speed in a circle has its acceleration vector always:','MCQ','2','Easy','Y','Centripetal acceleration is always directed radially inward, perpendicular to the (tangential) velocity.','N','N'),
    (110146,@subjectId,50102,@examId,'A stone is thrown horizontally with speed 10 m/s from a height of 20m (g=10 m/s^2). Time to hit the ground is:','MCQ','2','Easy','Y','h=(1/2)gt^2 => 20=5t^2 => t^2=4 => t=2s.','N','N'),
    (110147,@subjectId,50102,@examId,'For the stone in the previous scenario, the horizontal distance travelled before hitting the ground is:','MCQ','3','Easy','Y','Horizontal distance = horizontal speed x time = 10 x 2 = 20 m.','N','N'),
    (110148,@subjectId,50102,@examId,'A particle''s velocity-time graph is a straight line with negative slope passing through the time axis. This represents:','MCQ','1','Medium','Y','A straight line v-t graph crossing the t-axis shows constant (uniform) acceleration/deceleration, with velocity direction reversing at the crossing point.','N','N'),
    (110149,@subjectId,50102,@examId,'Average speed can be equal to the magnitude of average velocity only when:','MCQ','2','Medium','Y','If motion is along a straight line in one direction only (no reversal), distance equals displacement magnitude, making average speed equal average velocity magnitude.','N','N'),
    (110150,@subjectId,50102,@examId,'The equation v^2 = u^2 + 2as is valid for:','MCQ','2','Easy','Y','This third equation of motion applies to one-dimensional motion under constant acceleration.','N','N'),
    (110201,@subjectId,50103,@examId,'Newton''s first law of motion defines:','MCQ','2','Easy','Y','The first law states a body continues in its state of rest/motion unless acted on by a net force — this defines inertia.','N','N'),
    (110202,@subjectId,50103,@examId,'Newton''s second law states that force is:','MCQ','2','Easy','Y','F=dp/dt, the rate of change of linear momentum, which reduces to F=ma for constant mass.','N','N'),
    (110203,@subjectId,50103,@examId,'Newton''s third law implies that action-reaction forces:','MCQ','2','Easy','Y','Action and reaction act on two different bodies, so they never cancel for either individual body.','N','N'),
    (110204,@subjectId,50103,@examId,'A block of mass 5kg is pulled by force 20N on a frictionless surface. Its acceleration is:','MCQ','2','Easy','Y','a=F/m=20/5=4 m/s^2.','N','N'),
    (110205,@subjectId,50103,@examId,'The SI unit of momentum is:','MCQ','1','Easy','Y','Momentum p=mv, unit kg.m/s (equivalent to N.s).','N','N'),
    (110206,@subjectId,50103,@examId,'A rocket works on the principle of conservation of:','MCQ','2','Easy','Y','Rockets expel mass backward; by momentum conservation the rocket gains forward momentum.','N','N'),
    (110207,@subjectId,50103,@examId,'The coefficient of static friction is generally __ the coefficient of kinetic friction for the same surfaces.','MCQ','2','Medium','Y','Static friction coefficient is typically slightly greater than or equal to kinetic friction coefficient.','N','N'),
    (110208,@subjectId,50103,@examId,'A block on a rough incline of angle theta remains stationary. The condition is:','MCQ','1','Medium','Y','The block stays static as long as tan(theta) does not exceed the coefficient of static friction (mu_s).','N','N'),
    (110209,@subjectId,50103,@examId,'Impulse is equal to:','MCQ','2','Easy','Y','Impulse J = F x Δt = Δp, the change in momentum.','N','N'),
    (110210,@subjectId,50103,@examId,'A person standing in a stationary lift experiences normal force equal to:','MCQ','2','Easy','Y','With zero acceleration, N=mg by Newton''s second law (net force zero).','N','N'),
    (110211,@subjectId,50103,@examId,'Two masses m1 and m2 connected by a string over a frictionless pulley accelerate at:','MCQ','1','Medium','Y','For an Atwood machine, a=(m1-m2)g/(m1+m2), with m1>m2 assumed.','N','N'),
    (110212,@subjectId,50103,@examId,'A body of mass m moving with velocity v collides and stops in time t. The average force exerted on it is:','MCQ','1','Easy','Y','Average force = Δp/Δt = (mv-0)/t = mv/t.','N','N'),
    (110213,@subjectId,50103,@examId,'The tension in a string connecting two blocks being pulled horizontally on a frictionless surface depends on:','MCQ','2','Medium','Y','Tension depends on the masses of blocks involved and the net applied force producing their common acceleration.','N','N'),
    (110214,@subjectId,50103,@examId,'Friction is a type of:','MCQ','2','Medium','Y','Friction arises from electromagnetic interactions between surface molecules and is a contact force, not fundamental.','N','N'),
    (110215,@subjectId,50103,@examId,'A car moves in a circle on a level road. The centripetal force is provided by:','MCQ','3','Medium','Y','On a level (unbanked) road, friction between tyres and road surface provides the necessary centripetal force.','N','N'),
    (110216,@subjectId,50103,@examId,'For a banked road (no friction) of angle theta and radius r, the safe speed is:','MCQ','2','Medium','Y','v=sqrt(rg tan(theta)) balances gravity and normal reaction components to provide centripetal force with no friction needed.','N','N'),
    (110217,@subjectId,50103,@examId,'The recoil velocity of a gun firing a bullet follows from conservation of:','MCQ','2','Easy','Y','Total momentum before firing (zero) equals total momentum after (bullet forward + gun recoil backward).','N','N'),
    (110218,@subjectId,50103,@examId,'A lift accelerates downward with acceleration a < g. The apparent weight of a person of mass m is:','MCQ','2','Easy','Y','Apparent weight (normal force) = m(g-a) when accelerating downward with a<g.','N','N'),
    (110219,@subjectId,50103,@examId,'If a=g exactly for a downward accelerating lift (free fall), the apparent weight is:','MCQ','2','Easy','Y','In free fall, normal force becomes zero — the classic ''weightlessness'' condition.','N','N'),
    (110220,@subjectId,50103,@examId,'Which of the following is an example of pseudo (fictitious) force?','MCQ','2','Medium','Y','Centrifugal force appears only in non-inertial (rotating) reference frames and has no real interacting partner — a pseudo force.','N','N'),
    (110221,@subjectId,50103,@examId,'The linear momentum of a system of particles is conserved when:','MCQ','1','Easy','Y','Conservation of momentum holds whenever net external force on the system is zero (Newton''s laws).','N','N'),
    (110222,@subjectId,50103,@examId,'A 2kg block on a frictionless surface is acted upon by two forces, 10N east and 6N west. Its acceleration is:','MCQ','2','Easy','Y','Net force=10-6=4N east; a=F/m=4/2=2 m/s^2 east.','N','N'),
    (110223,@subjectId,50103,@examId,'Which law of motion is often called the ''law of inertia''?','MCQ','1','Easy','Y','Newton''s first law describes inertia — the tendency of objects to resist changes in their state of motion.','N','N'),
    (110224,@subjectId,50103,@examId,'A machine gun fires n bullets per second, each of mass m with velocity v. The force needed to hold the gun steady is:','MCQ','1','Medium','Y','Force = rate of change of momentum imparted = (number of bullets/sec) x (momentum per bullet) = n x m x v.','N','N'),
    (110225,@subjectId,50103,@examId,'The maximum static friction force is given by:','MCQ','1','Easy','Y','Limiting static friction f_s(max) = mu_s N, where N is the normal reaction force.','N','N'),
    (110226,@subjectId,50103,@examId,'A block of mass m is at rest on a rough horizontal surface with coefficient of friction mu. The minimum force to just start moving it (applied horizontally) is:','MCQ','1','Easy','Y','To overcome limiting static friction, applied force must at least equal mu*m*g (assuming N=mg on a horizontal surface).','N','N'),
    (110227,@subjectId,50103,@examId,'Conservation of momentum in a collision holds true:','MCQ','3','Medium','Y','Momentum conservation applies to any collision (elastic or inelastic) in an isolated system, unlike kinetic energy which is conserved only in elastic collisions.','N','N'),
    (110228,@subjectId,50103,@examId,'A 1kg ball moving at 4 m/s collides head-on with a stationary 1kg ball and they stick together. Their common velocity after collision is:','MCQ','2','Medium','Y','By momentum conservation: 1x4+1x0=(1+1)v => v=2 m/s.','N','N'),
    (110229,@subjectId,50103,@examId,'The normal reaction on a block placed on an incline of angle theta (mass m) is:','MCQ','2','Easy','Y','Component of weight perpendicular to incline = mg cos(theta), balanced by normal reaction.','N','N'),
    (110230,@subjectId,50103,@examId,'The component of gravity along a frictionless incline of angle theta causing a block to slide is:','MCQ','2','Easy','Y','Component along the incline (causing sliding) is mg sin(theta).','N','N'),
    (110231,@subjectId,50103,@examId,'Which of these best explains why it''s harder to start pushing a heavy box than to keep it moving?','MCQ','1','Medium','Y','Since limiting static friction typically exceeds kinetic friction, more force is needed to initiate motion than to sustain it.','N','N'),
    (110232,@subjectId,50103,@examId,'A body is under the action of three concurrent forces and is in equilibrium. This implies:','MCQ','2','Easy','Y','Equilibrium under concurrent forces requires their vector sum to be zero (Lami''s theorem context).','N','N'),
    (110233,@subjectId,50103,@examId,'For circular motion of a car on a banked road WITH friction, the maximum safe speed is:','MCQ','1','Hard','Y','Friction can additionally assist providing centripetal force beyond what banking alone offers, so maximum safe speed increases with friction (up to the friction limit).','N','N'),
    (110234,@subjectId,50103,@examId,'The concept of impulse is most useful in analysing:','MCQ','2','Easy','Y','Impulse (J=FΔt=Δp) is especially useful for impact/collision problems, where force acts over a very short duration but can be characterized simply by momentum change.','N','N'),
    (110235,@subjectId,50103,@examId,'Newton''s second law in the form F=ma is valid strictly for:','MCQ','2','Medium','Y','F=ma applies rigorously in inertial (non-accelerating) frames and assumes constant mass; variable-mass systems need F=dp/dt more generally.','N','N'),
    (110236,@subjectId,50103,@examId,'A block placed on a truck bed that is accelerating forward tends to slide backward relative to the truck due to:','MCQ','2','Medium','Y','The block''s inertia resists the forward acceleration; unless friction provides enough forward force, it appears to slide backward relative to the truck.','N','N'),
    (110237,@subjectId,50103,@examId,'Which pair of forces constitutes a valid action-reaction pair?','MCQ','2','Medium','Y','True action-reaction pairs act on different bodies and are of the same type — book pushes table down, table pushes book up, equal and opposite.','N','N'),
    (110238,@subjectId,50103,@examId,'A 4kg object experiences a net force of 12N. Its acceleration is:','MCQ','1','Easy','Y','a=F/m=12/4=3 m/s^2.','N','N'),
    (110239,@subjectId,50103,@examId,'Conservation of momentum applied to an explosion of a stationary object into two fragments implies the fragments move:','MCQ','2','Medium','Y','Initial momentum is zero; the two fragments must have equal and opposite momenta to keep total momentum zero.','N','N'),
    (110240,@subjectId,50103,@examId,'Which of the following increases the stopping distance of a vehicle for the same initial speed?','MCQ','2','Medium','Y','Lower friction means less deceleration force, so it takes a longer distance to stop for the same initial speed.','N','N'),
    (110241,@subjectId,50103,@examId,'A spring balance reads the: ','MCQ','2','Medium','Y','A spring balance actually measures the force (weight) via spring extension, calibrated assuming standard g to display a mass reading.','N','N'),
    (110242,@subjectId,50103,@examId,'Two blocks of mass m1 and m2 in contact are pushed by force F on a frictionless surface. The contact force between them (m1 pushing m2) is:','MCQ','2','Hard','Y','Common acceleration a=F/(m1+m2); contact force on m2 = m2*a = F*m2/(m1+m2).','N','N'),
    (110243,@subjectId,50103,@examId,'Rolling friction is generally __ sliding friction.','MCQ','2','Easy','Y','Rolling friction coefficients are typically much smaller than sliding/kinetic friction coefficients, which is why wheels reduce resistance.','N','N'),
    (110244,@subjectId,50103,@examId,'A ball of mass m falling freely experiences a net force equal to:','MCQ','2','Easy','Y','In free fall (ignoring air resistance) the only force is gravity, mg downward, producing acceleration g.','N','N'),
    (110245,@subjectId,50103,@examId,'The ''weight'' of an object is best defined as:','MCQ','2','Easy','Y','Weight = mg, the gravitational force experienced by the object''s mass, distinct from the invariant quantity mass itself.','N','N'),
    (110246,@subjectId,50103,@examId,'A horse pulls a cart; by Newton''s third law, the cart pulls the horse backward with equal force. The cart still moves forward because:','MCQ','1','Hard','Y','The horse-cart pair moves due to the external force of ground friction on the horse''s feet exceeding the backward pull from the cart; action-reaction pairs act on different objects so they don''t cancel for the system''s motion.','N','N'),
    (110247,@subjectId,50103,@examId,'A 0.5kg ball hits a wall at 6 m/s and bounces back at 4 m/s. The magnitude of change in momentum is:','MCQ','3','Medium','Y','Δp = m(v_final - v_initial) taking directions into account = 0.5*(4-(-6))=0.5*10=5 kg.m/s.','N','N'),
    (110248,@subjectId,50103,@examId,'Static friction is a __ force (self-adjusting up to a limit).','MCQ','2','Easy','Y','Static friction adjusts itself to exactly balance the applied force up to its maximum limiting value, beyond which the body starts to slide.','N','N'),
    (110249,@subjectId,50103,@examId,'The concept of ''centre of mass'' is useful because the motion of a system of particles under external forces can be described as if:','MCQ','2','Medium','Y','The centre of mass moves as though all mass is concentrated there, obeying Newton''s second law with only the net external force.','N','N'),
    (110250,@subjectId,50103,@examId,'A rope can only exert a: ','MCQ','2','Easy','Y','Ropes/strings can only pull (tension); they cannot push (they would go slack instead).','N','N');

    -- Answer options

    -- Link all new questions to the Physics exam
    SELECT @examId, q.QuestionId, 'Y'
      FROM questions q
     WHERE q.ChapterInfoId = 50101 AND q.QuestionId BETWEEN 110001 AND 110051
       AND NOT EXISTS (
             SELECT 1 FROM exam_questions eq
              WHERE eq.ExamInfoId = @examId AND eq.QuestionId = q.QuestionId
           );
    SELECT @examId, q.QuestionId, 'Y'
      FROM questions q
     WHERE q.ChapterInfoId = 50102 AND q.QuestionId BETWEEN 110101 AND 110150
       AND NOT EXISTS (
             SELECT 1 FROM exam_questions eq
              WHERE eq.ExamInfoId = @examId AND eq.QuestionId = q.QuestionId
           );
    SELECT @examId, q.QuestionId, 'Y'
      FROM questions q
     WHERE q.ChapterInfoId = 50103 AND q.QuestionId BETWEEN 110201 AND 110250
       AND NOT EXISTS (
             SELECT 1 FROM exam_questions eq
              WHERE eq.ExamInfoId = @examId AND eq.QuestionId = q.QuestionId
           );

    COMMIT;
END$$

DELIMITER ;

