  `UIRating` tinyint(4) DEFAULT NULL COMMENT '1–5 user-interface rating',
  `PerfRating` tinyint(4) DEFAULT NULL COMMENT '1–5 speed / performance rating',
  `QualityRating` tinyint(4) DEFAULT NULL COMMENT '1–5 question quality rating',
  `SupportRating` tinyint(4) DEFAULT NULL COMMENT '1–5 support / help rating',
  `Categories` varchar(500) DEFAULT NULL COMMENT 'CSV of areas: UI,Exam,Questions,Performance,Support,Registration',
  `LikedMost` text DEFAULT NULL COMMENT 'What did you like most?',
  `Improvements` text DEFAULT NULL COMMENT 'What could be improved?',
  `FeatureRequests` text DEFAULT NULL COMMENT 'Features you would like to see',
  `WouldRecommend` enum('Yes','No','Maybe') DEFAULT NULL,
  `UserRole` varchar(30) DEFAULT NULL COMMENT 'Student / Teacher / Admin at time of submission',
  `InstituteId` int(11) DEFAULT NULL COMMENT 'FK → institutes.InstituteId',
  `IpAddress` varchar(45) DEFAULT NULL,
  `CreatedAt` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='User feedback and suggestions for the Bodhika exam application';

