--
-- Table structure for table `certificates`
--

CREATE TABLE `certificates` (
  `CertificateId` int(10) UNSIGNED NOT NULL,
  `CertificateNo` varchar(40) NOT NULL COMMENT 'Public-facing unique cert number, e.g. CERT-2026-00001',
  `TemplateId` int(10) UNSIGNED NOT NULL,
  `UserInfoId` int(10) UNSIGNED NOT NULL COMMENT 'userinfo.UserInfoId',
  `SubjectInfoId` int(10) UNSIGNED DEFAULT NULL,
  `ExamInfoId` int(10) UNSIGNED DEFAULT NULL COMMENT 'NULL for manually-entered (non-exam-linked) completions',
  `StudentName` varchar(150) NOT NULL COMMENT 'Snapshot at issue time',
  `CourseName` varchar(200) NOT NULL COMMENT 'Snapshot at issue time',
  `Duration` varchar(100) DEFAULT NULL,
  `IssueDate` date NOT NULL,
  `Score` decimal(8,2) DEFAULT NULL,
  `MarksOutOf` decimal(8,2) DEFAULT NULL,
  `Percentage` decimal(5,2) DEFAULT NULL,
  `Grade` varchar(20) DEFAULT NULL COMMENT 'Distinction / A+ / A / B+ / B / Pass — merit certificates only',
  `CertType` enum('completion','merit') NOT NULL,
  `Status` enum('Issued','Revoked') NOT NULL DEFAULT 'Issued',
  `IssuedBy` varchar(100) NOT NULL DEFAULT '' COMMENT 'Admin display name who issued it',
  `GeneratedFile` varchar(255) DEFAULT NULL COMMENT 'certificates/generated/xxx.docx — filled Word document produced at issue time, TemplateType=word only',
  `IssuedAt` datetime NOT NULL DEFAULT current_timestamp(),
  `ExtraFields` mediumtext DEFAULT NULL COMMENT 'JSON snapshot of custom (non-catalog) field values used to fill a word template, e.g. {"START_DATE":"4 Mar 2026","END_DATE":"10 Mar 2026"}'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Issued certificates — immutable snapshot, not recomputed live';

