--
-- Table structure for table `certificate_templates`
--

CREATE TABLE `certificate_templates` (
  `TemplateId` int(10) UNSIGNED NOT NULL,
  `Name` varchar(100) NOT NULL,
  `CertType` enum('completion','merit') NOT NULL,
  `InstituteId` int(10) UNSIGNED DEFAULT NULL COMMENT 'Owning institute for image templates. NULL = global/built-in coded theme, usable by every institute.',
  `TemplateType` enum('coded','image','word') NOT NULL DEFAULT 'coded' COMMENT 'coded = ThemeKey CSS theme; image = uploaded background + positioned placeholders; word = uploaded .docx with {{TOKEN}} placeholders',
